INSERT INTO public.discussions (id, topic, type, trader, notes, tags, created_at, deleted_at) VALUES ('5', 'Risk Management in Day Trading', 'risk', 'Умид', 'Most important rule - always know your exit before entry. Position sizing formula: 2% per trade max. Fixed dollar stops beat percent stops always.', 'risk-management', '2026-04-09 10:30:06.758+00', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.discussions (id, topic, type, trader, notes, tags, created_at, deleted_at) VALUES ('4', 'Fade Trading and HOD Failures', 'strategy', 'Рахматулло', 'How do you identify which fades work? I see a lot of HOD failures that turn into runners. Any specific criteria you use to filter?', 'fade, short', '2026-04-09 10:30:06.758+00', NULL) ON CONFLICT DO NOTHING;
