INSERT INTO public.daily_feed (id, date, what_works_now, what_doesnt_work, best_tickers, market_theme, notes, tags, screenshot_url, screenshot_notes, created_at, deleted_at) VALUES ('1', '2026-04-07', NULL, NULL, 'UNH, CVS, HUM, CNC, MOH', 'Healthcare', 'Акции крупных медицинских страховщиков — UnitedHealth, Humana и CVS Health — выросли на 6–10% в ходе предпродовой сессии после того, как CMS объявила о повышении выплат по программе Medicare Advantage на 2,48% в 2027 году. Это показатель оказался лучше ожиданий рынка, особенно на фоне того, что в начале года предложенная надбавка в 0,99% уже обвалила акции UnitedHealth почти на 20% за один день.', 'Reversal, Gap Up, Breakout, News, Sector Move, Relative Strength, Wide Spread, High Volatility, News Risk, Market Weak', 'https://www.tradingview.com/x/Kx08uyL8/\nhttps://www.tradingview.com/x/RoAZqVUP/\nhttps://www.tradingview.com/x/YlaCWNQE/\nhttps://www.tradingview.com/x/83k2rYJq/\nhttps://www.tradingview.com/x/aq07OYla/', '["UNH, Принт по гепу, рисовки в маркет превратились","CVS, Принт против гепа.","HUM, Принт против гепа.","CNC, Принт flat.","MOH, Принт против гепа."]', '2026-04-09 10:30:06.712+00', NULL) ON CONFLICT DO NOTHING;
