INSERT INTO public.market_events (id, ticker, date, event_type, headline, reaction, percent_move, volume, summary, screenshot_url, screenshot_notes, tags, created_at, deleted_at) VALUES ('3', 'AVGO', '2026-04-07', 'news', 'Партнерство с GOOGLE.', 'gap_up', '4.00', '32.3', 'Broadcom заключила долгосрочное соглашение с\nGoogle по разработке и поставке AI-чипов до 2031 года.\n\nСоглашение предусматривает создание и поставку будущих поколений кастомных чипов для искусственного интеллекта.\n\nТакже заключено отдельное соглашение с\nAnthropic:\n\nBroadcom будет обеспечивать около 3.5 гигаватт вычислительной мощности, начиная с 2027 года.\n\nКомпания раскрыла информацию об этих сделках в отчёте, поданном в\nSEC, где описаны расширенные долгосрочные партнёрства в сфере ИИ.\n\nКомментарий: На премаркете было ложное пробитие хая премаркета. Потом вернулась в канал проторговки афтермаркета. Не показывала силу либо слабость на премаркете. В конце премаркета она вышла из канала проторговки афтермаркета , ретест и отросла. До 200 ma она не дошла на премаркете и афтемаркете. Цена открылась, спайк наверх, пробила 200 ma и вернулась. Несколько раз тестила 200 ma. В итоге начала падать и торговаться ниже опена. В 11:10 начала ходить за рынком росла. В итоге пробила 200 ma и вернулась. Кружится вокруг своей 200 ma.', NULL, NULL, NULL, '2026-04-09 10:30:06.618+00', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('125', 'Dollar Cost Into Winner — Pyramiding', 'Position Management', 'Другой', 'When trade is working, add to the position (pyramid) at predetermined levels. Maximize winners, don''t just take profit.', '- Initial entry at planned level (full or partial)\n- First add: after breakout confirms (price + volume)\n- Second add: on first pullback that holds\n- Each add is smaller than the previous\n- Move stop to breakeven after first add\n- Trail stop to lock in profits on adds\n- Never add to losers\n- Max position: 3 tiers', 'Pyramiding into winners is how prop traders maximize their best trades. SMB calls this ''pressing your winners.'' The key: each add must be smaller, and the stop must move up. Never average down — that''s the opposite of this strategy.', '80', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:54:49.931+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('124', 'CPI / Jobs Report — Morning Gap Framework', 'Macro & Sector Plays', 'Другой', 'Major economic data (CPI, NFP, PPI) released at 8:30 AM ET. Creates significant gaps. Trade the gap framework after open.', '- Note data release at 8:30 AM (pre-market)\n- Calculate gap vs expectations\n- If data better than expected = bullish gap (usually)\n- If data worse = bearish gap\n- Wait for market open, don''t pre-market trade\n- Apply Gap and Go or Gap Fill framework\n- Sector impact: CPI → tech/growth, Jobs → financials\n- Reduce size on macro days', 'Macro data days create the biggest moves because they affect ALL stocks simultaneously. CPI and jobs data move the entire market. Key: don''t trade the data, trade the reaction to the data. The same CPI number can be bullish or bearish depending on context.', '67', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:54:49.888+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('123', 'Fed Day / FOMC — 2:00 PM Reversal', 'Macro & Sector Plays', 'Другой', 'FOMC announcement at 2:00 PM ET. Initial move often reverses. Wait for the ''whipsaw'' and trade the real direction.', '- No new positions before 2:00 PM on FOMC day\n- Note initial reaction direction at 2:00 PM\n- Wait 15-30 minutes for the ''whipsaw''\n- If initial move reverses = trade the reversal\n- If initial move continues with volume = trade continuation\n- Reduce size (FOMC = volatile)\n- Stop tight (FOMC moves are fast)\n- Close all FOMC trades by end of day', 'FOMC days have a well-known pattern: initial spike at 2:00 PM, then reversal, then the ''real'' move. The initial reaction is often wrong because algorithms react to headlines before the full statement is analyzed. Patience is key.', '62', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:54:49.845+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('122', 'Sector Rotation — Follow the Money', 'Macro & Sector Plays', 'Другой', 'Money rotates between sectors based on economic cycle. Identify which sectors are receiving inflows and trade the leaders.', '- Monitor sector ETF relative performance (XLF, XLE, XLK, etc.)\n- Identify sector showing 3+ days of outperformance\n- Find leading stocks within that sector\n- Entry on pullback in the leading stock\n- Confirm with sector ETF still trending\n- Stop if sector rotation reverses\n- Target: sector trend continuation', 'Sector rotation is driven by institutional portfolio rebalancing. When the economy shifts, trillions of dollars rotate. Early identification = riding the institutional wave. Track XL_ ETFs daily for rotation signals.', '72', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:54:49.802+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('121', 'Earnings Range Anticipation — Straddle Alternative', 'Earnings Strategies', 'Другой', 'Anticipate the earnings range based on implied move. Trade the break of that range rather than guessing direction.', '- Calculate expected move from options (straddle price)\n- Mark expected range (close +/- expected move)\n- After earnings: if price exceeds expected range = continuation\n- If price within expected range = mean reversion to close\n- Entry on confirmation of scenario\n- Stop based on expected range boundary\n- Target: 1.5x expected move (if exceeded) or prior close (if within)', 'Instead of guessing earnings direction, this framework uses the options market''s expected move as a roadmap. When the actual move exceeds expectations, momentum is real. When it stays within, the move is priced in.', '50', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:54:49.76+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('120', 'Post-Earnings Drift (PEAD) — Follow Surprise', 'Earnings Strategies', 'Другой', 'After earnings surprise, stock continues drifting in the direction of the surprise for days/weeks. Trade the drift, not the gap.', '- Significant earnings surprise (>10% above/below estimates)\n- Initial gap confirmed by volume\n- Wait for first pullback (don''t chase the gap)\n- Entry on pullback in direction of surprise\n- Positive surprise: long pullback to VWAP/21EMA\n- Negative surprise: short bounce to VWAP/21EMA\n- Hold: 5-20 days\n- Trail stop using 8 EMA daily', 'Post-Earnings Announcement Drift (PEAD) is one of the most well-documented anomalies in finance. Studies show stocks continue moving in the direction of the earnings surprise for 60+ days. The market underreacts to earnings surprises.', '74', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:54:49.717+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('119', 'Earnings Whisper — Pre-Earnings Position', 'Earnings Strategies', 'Другой', 'Accumulate position before earnings when technical setup + whisper numbers suggest upside surprise. Small size for binary risk.', '- Earnings within 1-3 days\n- Technical setup bullish (above MAs, tight range)\n- Options IV < historical norm (cheap options)\n- Whisper number higher than consensus\n- Revenue growth trend positive\n- Entry: small position (25-50% normal size)\n- Define max loss BEFORE entry\n- Exit plan for both scenarios', 'Pre-earnings positions are high-risk binary trades. SMB teaches: if you trade earnings, use reduced size and define your max loss before entry. The best risk/reward comes when options IV is below average — you''re getting paid less for the uncertainty.', '58', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:54:49.675+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('118', 'Fibonacci Retracement — Measured Pullback', 'Swing Trading Setups', 'Breakout', 'Stock in trend pulls back to key Fibonacci level (38.2%, 50%, 61.8%). Enter at Fib level with stop below next Fib.', '- Identify clear trend (impulse move)\n- Draw Fibonacci from swing low to swing high (uptrend)\n- Wait for pullback to 38.2%, 50%, or 61.8% level\n- Look for reversal candle at Fib level\n- Volume should decrease on pullback\n- Entry on bounce from Fib with volume\n- Stop below next Fib level\n- Target: retest of prior high or 1.618 extension', 'Fibonacci levels are self-fulfilling because so many traders use them. The 61.8% level is especially powerful — it''s the ''golden ratio'' pullback. If price holds 61.8%, the trend is likely intact. Below 78.6% = trend likely failed.', '71', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:54:49.632+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('117', 'Moving Average Crossover — Trend Change', 'Swing Trading Setups', 'Другой', '8/21 EMA crossover on daily chart signals trend change. Enter in direction of the cross with swing time frame.', '- 8 EMA crosses above 21 EMA = bullish\n- 8 EMA crosses below 21 EMA = bearish\n- Volume confirms crossover\n- Wait for pullback to 8 EMA after cross\n- Entry on bounce off 8 EMA in crossover direction\n- Stop: below 21 EMA\n- Target: prior swing high/low or Fibonacci extension\n- Hold: 5-20 days', 'EMA crossovers lag by nature but filter noise. The 8/21 combo captures trend changes faster than 50/200. Best used as a trend filter — take only long setups when 8>21, short setups when 8<21.', '63', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:54:49.59+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('115', 'Exhaustion Gap — Reversal Signal', 'Gap Trading', 'Gap', 'After an extended multi-day move, a final gap in the trend direction signals exhaustion. Trade the reversal.', '- Stock has moved >20% in one direction over 3-5 days\n- Final gap in the same direction (up gap after rally, down gap after selloff)\n- Volume highest of the entire move\n- Intraday reversal candle forms (shooting star, doji)\n- Entry on reversal confirmation\n- Stop above/below exhaustion gap extreme\n- Target: 38-50% retrace of entire move', 'Exhaustion gaps are one of the most reliable reversal signals in technical analysis. They represent the last burst of momentum before the trend reverses. Key identifier: the gap comes AFTER a multi-day move, not at the beginning.', '65', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:54:49.505+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('114', 'Gap and Trap — False Breakout', 'Gap Trading', 'Gap', 'Stock gaps up through resistance but immediately sells off. The gap traps breakout buyers. Short the trapped longs as they panic.', '- Stock gaps above key resistance level\n- First 15 minutes: selling pressure emerges\n- Stock falls back below resistance (now support becomes resistance)\n- Trapped longs begin to panic sell\n- Entry short on break below gap low or key level\n- Volume increases on the reversal\n- Stop above gap high\n- Target: prior support or gap fill', 'Gap and Trap is the opposite of Gap and Go. It works because breakout buyers get trapped when the gap fails. Their stop-loss selling accelerates the move down. Best when the gap is on weak catalyst or into major resistance.', '72', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:54:49.462+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('113', 'Gap Fill — Statistical Edge', 'Gap Trading', 'Gap', 'Most gaps fill within 1-3 days (statistical tendency). Trade the gap fill when conditions support mean reversion back to prior close.', '- Gap without strong catalyst (earnings, FDA excluded)\n- Gap size < 5% (large gaps less likely to fill same day)\n- Pre-market volume normal (not elevated)\n- If gap up: short toward prior close\n- If gap down: long toward prior close\n- Entry after first 15 min (avoid opening volatility)\n- Stop beyond gap extreme\n- Target: prior day close (full fill)', 'Statistical studies show ~70% of gaps eventually fill. However, catalyst-driven gaps (earnings, FDA) fill less often. Best gap fill trades are on ''nothing'' gaps — gap on no real news, just overnight drift.', '70', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:54:49.42+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('112', 'Pairs Trade — Relative Value', 'Mean Reversion Plays', 'Другой', 'Two correlated stocks diverge. Long the underperformer, short the outperformer. Profit when the spread reverts to mean.', '- Identify correlated pair (same sector, similar business)\n- Calculate historical spread (ratio or price difference)\n- Wait for spread to reach 2+ StdDev from mean\n- Long the laggard, short the leader (equal dollar amounts)\n- Monitor correlation — if it breaks, exit\n- Target: spread returns to mean\n- Max hold: 5-10 days', 'Pairs trading is market-neutral — you profit from the relative move, not the absolute direction. Classic pairs: XOM/CVX, GOOGL/META, JPM/BAC. Risk: the correlation can break permanently (structural change).', '75', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:54:49.376+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('111', 'Rubber Band Snap — Extended Stock Reversal', 'Mean Reversion Plays', 'Reversal', 'Stock stretched far from VWAP or moving average like a rubber band. Trade the snap-back to the mean when momentum exhausts.', '- Stock >2% from VWAP (intraday) or >5% from 20MA (daily)\n- Momentum indicators showing divergence\n- Volume decreasing on the extension\n- Candle pattern showing reversal (doji, hammer, engulfing)\n- Entry on reversal confirmation\n- Stop beyond the extreme\n- Target: VWAP or moving average', 'The rubber band analogy: the further a stock stretches from its mean, the more energy is stored for the snap-back. Works best when the extension is on declining volume — showing exhaustion rather than genuine trend.', '68', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:54:49.334+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('110', 'Mean Reversion — Oversold Bounce', 'Mean Reversion Plays', 'Reversal', 'Stock drops >3 standard deviations from its mean (20-day MA). Statistical probability favors a bounce. Long the oversold condition.', '- Stock >3 StdDev below 20-day MA\n- RSI < 20 on daily chart\n- No fundamental catalyst for further downside\n- Volume exhaustion (decreasing on sell-off)\n- Entry on first green candle after selling exhaustion\n- Stop below recent low\n- Target: 20-day MA (mean)', 'Mean reversion works because extreme moves are statistically unsustainable. However, key filter: avoid stocks with ongoing fundamental deterioration (bankruptcy risk, fraud, etc.). Best on large-cap with temporary panic.', '72', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:54:49.29+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('109', 'Level 2 Spoofing Detection', 'Advanced Tape Reading', 'Другой', 'Detect spoofing on Level 2 — large orders that appear and disappear to manipulate price. Trade opposite the spoof direction.', '- Watch for large bid/ask orders that repeatedly cancel\n- Spoof orders usually >50K shares on illiquid stocks\n- Note if price moves toward the spoof, then spoof is removed\n- Real orders get filled, spoof orders get cancelled\n- If large bid keeps disappearing = fake support = bearish\n- If large ask keeps disappearing = fake resistance = bullish\n- Use tape confirmation before entry', 'Spoofing is illegal but still occurs, especially on small/mid cap stocks. Recognizing it gives you an edge because you understand which levels are real and which are fake. Key: real orders absorb volume, spoof orders run.', '60', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:54:49.246+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('108', 'Dark Pool Print — Hidden Liquidity', 'Advanced Tape Reading', 'Другой', 'Unusually large dark pool prints signal institutional interest. Trade in direction of the largest prints when they cluster at a price level.', '- Monitor dark pool print data (Finra ADF, TRF)\n- Look for prints >100K shares\n- Note price level where prints cluster\n- If prints at/above ask = bullish\n- If prints at/below bid = bearish\n- Use as confirmation, not primary signal\n- Combine with chart pattern for entry', 'Dark pools account for ~40% of US equity volume. Large institutional orders often execute there to avoid market impact. When you can see these prints, you''re seeing what smart money is doing.', '65', NULL, NULL, 'Dark Pool Print,Block Trade Follow,Tape Reading Entry,Dark Pool Level,Dark Pool Volume', NULL, NULL, '2026-04-09 23:54:49.203+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('107', 'Tape Reading — Order Flow Entry', 'Advanced Tape Reading', 'Другой', 'Read Level 2 / Time & Sales to identify institutional activity. Large prints, hidden orders, and bid/ask dynamics reveal intent.', '- Watch Time & Sales for large prints (>10K shares)\n- Note bid/ask size imbalances on Level 2\n- Look for iceberg orders (repeated same-size prints)\n- Identify institutional accumulation vs distribution\n- Entry when tape confirms your directional bias\n- Stop if tape reading thesis is invalidated', 'Tape reading is the original edge. Before charts, traders read the tape. Large prints at the ask = buying pressure. Large prints at the bid = selling pressure. SMB Capital considers tape reading a core skill.', '78', NULL, NULL, 'Tape Reading Entry,Level 2 Entry,Dark Pool Print,Block Trade Follow,High Relative Volume', NULL, NULL, '2026-04-09 23:54:49.16+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('106', 'Overnight Hold — Swing Catalyst', 'Pre-Market & After Hours', 'Другой', 'Hold position overnight when catalyst supports multi-day move. Reduce size for overnight risk. Set hard stop.', '- Catalyst supports multi-day move (earnings beat, FDA, M&A)\n- Reduce position to 50% of intraday size\n- Set hard stop (worst-case exit level)\n- Calculate overnight gap risk\n- Check after-hours liquidity\n- Set pre-market alert for review\n- Re-evaluate at next open', 'Overnight holds add gap risk but capture multi-day moves. Key rule: if you wouldn''t enter the position fresh at the close, don''t hold it overnight. Always reduce size.', '55', NULL, NULL, 'Swing Hold,Overnight Hold Gap,Multi-Day Momentum,Earnings Beat,FDA Approval', NULL, NULL, '2026-04-09 23:54:49.118+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('105', 'After Hours Earnings React — Next Day Prep', 'Pre-Market & After Hours', 'Другой', 'Stock reports earnings after hours. Analyze reaction, prepare next-day game plan based on after-hours price action.', '- Note earnings results vs expectations\n- Watch after-hours price reaction\n- Identify key AH levels (high, low, close)\n- Check options implied move vs actual\n- Prepare bull/bear scenario for next day\n- Set pre-market alerts', 'After-hours reaction to earnings often sets the tone for the next trading day. Preparing the night before gives you a significant edge over traders who react in real-time.', '70', NULL, NULL, 'Earnings Gap Up,Earnings Gap Down,Second Day Play,After Hours,Earnings Beat,Earnings Miss', NULL, NULL, '2026-04-09 23:54:49.075+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('104', 'Pre-Market Gap Scan — Watchlist Build', 'Pre-Market & After Hours', 'Другой', 'Before market open (7:00-9:30 AM ET). Scan for stocks gapping >4% on catalyst. Build watchlist with levels, plan entries.', '- Scan at 7:00 AM for gaps >4%\n- Check catalyst (earnings, news, upgrade/downgrade)\n- Note pre-market volume (>500K = in play)\n- Mark key levels: PM high, PM low, prior day close\n- Calculate ATR for position sizing\n- Rank top 3-5 stocks by catalyst quality\n- Set alerts at key levels', 'The most important 30 minutes of the day happens before the market opens. Every successful prop trader starts with a thorough pre-market scan. This framework ensures you''re prepared, not reactive.', '85', NULL, NULL, 'Gap Up,Gap Down,Premarket,Premarket High,Premarket Low,High Relative Volume', NULL, NULL, '2026-04-09 23:54:49.032+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('103', 'MOC + Options Expiration — Pin Risk Play', 'MOC / Closing Auction', 'Другой', 'On options expiration (monthly/weekly), stocks tend to ''pin'' to strike prices with maximum open interest. Trade the pin into the close.', '- Identify max pain / highest OI strike price\n- After 2:00 PM on OPEX day, monitor price vs strike\n- If stock near high-OI strike, expect pinning action\n- Trade toward the pin strike (mean reversion to strike)\n- MOC order at the pin strike if profitable\n- Size small — pinning is not guaranteed\n- Works best on large-cap with high options volume\n- Close all positions at market close', 'Options expiration pinning occurs because market makers hedge their delta by buying/selling stock. As options expire, this hedging creates mean-reversion toward the highest open interest strike. This effect is strongest in the last 2 hours of OPEX day.', '62', NULL, NULL, 'MOC Imbalance,Closing Cross Play,Imbalance,OPEX Day,Last Hour,Round Number', NULL, NULL, '2026-04-09 23:54:48.901+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('102', 'MOC Fade — Closing Reversal', 'MOC / Closing Auction', 'Другой', 'After an extreme closing imbalance pushes price, the next morning often sees a reversal. Fade the closing auction move at next open.', '- Large closing imbalance pushed price >0.5% in last 15 min\n- The move was mechanical (rebalance) not fundamental\n- Next day: fade the closing move direction\n- Entry: at open or first 15 min of next day\n- Target: prior day''s 3:45 PM price (pre-imbalance level)\n- Stop: beyond closing price\n- Works best on quarterly rebalance days\n- Avoid if fundamental catalyst exists', 'Closing imbalances are mechanical — index funds MUST buy or sell regardless of price. This creates artificial moves that often reverse the next morning when the forced buying/selling is done. Key: only fade mechanical moves, not fundamental ones.', '60', NULL, NULL, 'MOC Imbalance,Closing Cross Play,Fade Trade,Reversal,Last Hour,Power Hour', NULL, NULL, '2026-04-09 23:54:48.859+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('101', 'MOC Imbalance — Closing Auction Play', 'MOC / Closing Auction', 'Другой', 'NYSE publishes closing imbalance data at 3:45 PM. Large MOC imbalances create predictable price moves into the close. Trade the last 15 minutes.', '- Check closing imbalance at 3:45 PM ET\n- Buy imbalance > 500K shares = bullish into close\n- Sell imbalance > 500K shares = bearish into close\n- Entry at 3:45-3:50 PM in direction of imbalance\n- Price typically moves toward imbalance direction\n- Quick trade: entry 3:45, exit at close or MOC\n- No overnight hold required\n- Best on index rebalance / options expiration days', 'Closing imbalances are the most predictable short-term trades in the market. Index funds, ETFs, and institutional rebalancing create massive order imbalances at the close. On rebalancing days, these can be >$2B. The price MUST adjust to fill these orders.', '73', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:54:48.816+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('100', 'MOC — Market On Close Order', 'MOC / Closing Auction', 'Другой', 'Use MOC (Market-On-Close) order to participate in the NYSE closing auction. Capture the closing print for next-day gap positioning.', '- MOC orders must be submitted by 3:45 PM ET (NYSE) or 3:50 PM (NASDAQ)\n- Determine direction based on day''s trend (above/below VWAP)\n- Size: 50% of normal for overnight risk\n- MOC guarantees fill at official closing price\n- Cannot cancel after 3:45 PM deadline\n- Best for next-day catalyst plays (earnings AH, overnight events)\n- Review closing imbalance data at 3:45 PM\n- Set overnight stop-loss alert', 'MOC orders are used by institutions to execute at the closing price — the most important price of the day. For prop traders, MOC is useful when you want to hold overnight and want the best closing price without chasing.', '76', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:54:48.774+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('99', 'IMBX + VWAP Confirmation', 'Imbalance (IMBX) Strategies', 'Imbalance', 'Combine imbalance data with VWAP direction. When opening imbalance aligns with VWAP trend (stock opens above/below VWAP in same direction as imbalance), the signal is strongest.', '- Buy imbalance + stock above developing VWAP = strong long\n- Sell imbalance + stock below developing VWAP = strong short\n- Entry on first pullback to VWAP after open\n- Volume must confirm direction\n- Contradictory signals (buy imbalance but below VWAP) = no trade\n- Stop: VWAP cross\n- Target: prior day level or measured move\n- This is a high-probability A+ setup when aligned', 'Combining two institutional signals (imbalance + VWAP) creates a high-probability setup. Institutions use both VWAP and auction data. When they agree, you''re aligned with smart money. When they contradict, stay flat.', '80', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:54:48.731+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('98', 'IMBX Fade — Imbalance Reversal', 'Imbalance (IMBX) Strategies', 'Imbalance', 'When opening imbalance is extreme but reverses by 9:28 AM, the initial move often reverses. Fade the expected direction.', '- Large imbalance at 9:20 (>1M shares one direction)\n- By 9:28 AM imbalance reduces significantly or flips\n- This signals the imbalance was absorbed / crossed\n- Trade opposite the original imbalance direction\n- Wait for open, then entry on reversal candle\n- Small size (counter-trend play)\n- Stop tight — opposite side of opening range\n- Target: VWAP', 'Imbalance fades are advanced plays. When a large buy imbalance at 9:20 gets paired off by 9:28, it means the selling interest absorbed the demand. The opening may still pop up, but it quickly reverses. This is a trap for imbalance-only traders.', '58', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:54:48.688+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('97', 'IMBX — Opening Imbalance Short', 'Imbalance (IMBX) Strategies', 'Imbalance', 'Significant sell imbalance (IMBX > 500K shares on sell side) at 9:20 AM. Strong selling pressure expected at open. Short into the imbalance.', '- Sell imbalance > 500K shares at 9:20+ AM\n- Confirm negative catalyst (earnings miss, downgrade)\n- Entry via OPG short or first bounce after open\n- Imbalance should be consistent and growing\n- Watch 9:28 AM final imbalance (most reliable)\n- Stop: if imbalance reverses significantly\n- Target: morning low or gap fill\n- Close by midday if not working', 'Sell imbalances create supply/demand asymmetry at the open. Institutions are net sellers and the opening price adjusts down. Key: the 9:28 AM imbalance is the most reliable — earlier readings can flip.', '74', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:54:48.645+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('96', 'IMBX — Opening Imbalance Long', 'Imbalance (IMBX) Strategies', 'Imbalance', 'NYSE/NASDAQ publish order imbalance data at 9:20 AM. Significant buy imbalance (IMBX > 500K shares) signals strong opening demand. Long into the imbalance.', '- Check imbalance data starting at 9:20 AM\n- Buy imbalance > 500K shares = significant\n- Confirm catalyst supports the direction\n- Entry via OPG order or first pullback after open\n- Imbalance should be consistent (not flipping)\n- Watch for paired-off vs total imbalance ratio\n- Stop: if imbalance reverses or VWAP breaks\n- Target: morning high or prior resistance', 'Order imbalance data is public and published by exchanges. A large buy imbalance means there are significantly more buy orders than sell orders for the open. This creates upward pressure on the opening price. Prop firms monitor this data religiously.', '74', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:54:48.602+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('95', 'OPG Momentum — Opening Auction Breakout', 'OPG / Auction Plays', 'OPG', 'Use OPG to ride momentum when opening auction price will be significantly different from prior close. Follow the smart money flow.', '- Pre-market shows strong directional bias\n- Imbalance data (if available) confirms direction\n- Submit OPG in direction of momentum\n- Immediately set stop after fill\n- Target 1: first 5-min range extreme\n- Target 2: VWAP or prior resistance/support\n- Scale out in thirds\n- Best on In Play stocks with catalyst', 'OPG momentum captures the institutional order flow at the open. When there''s a clear imbalance (more buy than sell orders), the opening price adjusts up and the momentum continues. Getting in at the auction = best possible entry.', '72', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:54:48.56+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('94', 'OPG Gap Fade — Auction Reversal', 'OPG / Auction Plays', 'OPG', 'Stock gaps significantly on weak catalyst. OPG order to fade the gap — enter opposite direction at the open, expecting gap fill.', '- Gap >3% but catalyst is weak or already priced in\n- Pre-market volume is moderate (not extreme)\n- No institutional upgrades/downgrades\n- Submit OPG order to fade gap direction\n- Size: 25-50% of normal\n- Target: gap fill (prior close)\n- Stop: beyond gap extreme +0.5%\n- Time limit: close by lunch if not working', 'Fading gaps at the open is risky but statistically favorable when the catalyst is weak. The OPG order ensures you get the exact opening price. Key: only fade gaps with no fundamental reason. Earnings/FDA gaps should NOT be faded.', '68', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:54:48.517+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('93', 'OPG — Opening Price Guarantee Order', 'OPG / Auction Plays', 'OPG', 'Use OPG (Market-On-Open) order to participate in the NYSE/NASDAQ opening auction. Capture the opening print when catalyst is clear overnight.', '- Strong overnight catalyst (earnings, news, upgrade)\n- Pre-market direction is clear and consistent\n- Submit OPG order before 9:28 AM ET\n- Size: 50% of normal (auction risk)\n- OPG executes only at the opening print\n- If no fill, order cancels automatically\n- Review fill vs pre-market price\n- Manage position from open', 'OPG orders guarantee you participate in the opening auction at the official opening price. This is how institutions enter positions. Advantage: no slippage from the open, you get the exact opening print. Best on gap days with clear catalyst.', '75', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:54:48.472+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('22', 'Earnings Gap Up — First Pullback Long', 'SMB Capital - Earnings Plays', 'Earnings Gap Up', 'Gap up >5% на отчётности с beat по EPS и revenue\nОбъём premarket >500K shares\nКлючевые уровни: вчерашний high, pre-market high, whole/half dollars\nКатализатор чистый — guidance raised или beat >10%\nНет значимого сопротивления в первые $2-3 от открытия', '- EPS beat >5%\n- Revenue beat >3%\n- Guidance raised или не снижен\n- Premarket volume >500K\n- Gap >5% от close\n- Float <100M (идеально <30M)\n- Нет earnings peer в тот же день\n- Risk/Reward минимум 3:1\n- Стоп под VWAP или low первого 5-мин бара', 'SMB Capital core setup. Ждём первый откат к VWAP или rising 9 EMA на 1-мин после opening drive. Вход на hold VWAP с тейком на новый HOD. Ключ — скорость recovery после pullback. Если recovery медленная (>3 мин), пропускаем.\n\nЛучшие дни: вторник-четверг. Избегать в дни FOMC/CPI.\n\nTrades to study: CELH earnings Aug 2023, SMCI earnings Jan 2024, ONON earnings multiple.', '90', NULL, NULL, 'earnings, gap-up, momentum, A+', NULL, NULL, '2026-04-09 10:30:06.853+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('21', 'Earnings Gap Down — Short the Failed Bounce', 'SMB Capital - Earnings Plays', 'Earnings Gap Down Short', 'Gap down >7% на miss по EPS или guidance cut\nОбъём premarket >300K\nСтруктура: opening drive down → bounce attempt → fail at resistance\nResistance: VWAP, prior close, declining 9 EMA\nSector weak или нейтральный', '- EPS miss или guidance cut\n- Gap down >7%\n- Bounce to VWAP or 38.2% retrace fails\n- Lower highs формируются на bounce\n- Volume fade на bounce\n- No major support nearby ($1-2 range)\n- Risk: above VWAP or bounce high\n- Target: LOD retest or extension', 'Ждём failed bounce к VWAP после утреннего sell-off. Вход short на rejection от VWAP или declining 9 EMA. Стоп выше VWAP. Тейк — retest LOD и ниже.\n\nОсторожно с акциями <$10 и с очень высоким short interest — могут сквизнуть.\n\nПримеры: SNAP earnings, ZM earnings drops, PYPL guidance cuts.', '82', NULL, NULL, 'earnings, gap-down, short, reversal', NULL, NULL, '2026-04-09 10:30:06.853+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('20', 'Earnings Winner — Day 2 Continuation', 'SMB Capital - Earnings Plays', 'Second Day Play', 'Day 1: сильный earnings gap up с close near HOD\nDay 2 gap up или flat open above Day 1 close\nОбъём Day 1 был >3x 20-day average volume\nНет распродажи premarket Day 2\nSector momentum positive', '- Day 1 closed >80% от range\n- Day 1 volume >3x average\n- Day 2 premarket: not fading below Day 1 close\n- Opening range first 5 min: above VWAP\n- Catalyst still fresh — upgrades/coverage\n- Entry: hold of Day 1 close or VWAP\n- Stop: below Day 1 close\n- Target: 1.5x Day 1 range extension', 'SMB classic Day 2 play. Самые сильные earnings movers продолжают движение на Day 2 из-за institutional buying, short covering, и upgrades overnight.\n\nКлюч — Day 1 close должен быть near HOD (закрытие силы). Если Day 1 закрылся с длинной верхней тенью, Day 2 обычно слабый.\n\nTrack: NVDA, META, AMZN post-earnings Day 2 moves.', '78', NULL, NULL, 'earnings, continuation, day-2, momentum', NULL, NULL, '2026-04-09 10:30:06.853+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('19', 'Opening Drive — Momentum Ignition', 'Intraday Momentum', 'Intraday Momentum', 'Гэп >3% с каталистом (news, upgrade, sector move)\nPremarket volume >200K\nBid-ask tight (<0.05 для stocks >$20)\nLevel 2 показывает стэковый bid\nFirst 1-min candle closes near high с volume >50K', '- Clear catalyst identified\n- Gap >3% with volume\n- First 1-min candle: bullish close\n- VWAP slope positive\n- No immediate overhead resistance ($0.50)\n- Entry: break of 1-min high\n- Stop: below 1-min low or VWAP\n- Target: next whole dollar / premarket high', 'Самый быстрый setup — первые 5-15 минут торгов. Вход на break первой 1-мин свечи с volume confirmation. Всё решается за 2-5 минут.\n\nОшибка новичков: входить в открытие без подтверждения первой свечи. Пропускайте если первая свеча — doji или bearish.\n\nWin rate ~55%, но R:R обычно 3:1+. Один из хлебных сетапов SMB.', '75', NULL, NULL, 'momentum, opening, speed, A-setup', NULL, NULL, '2026-04-09 10:30:06.853+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('31', 'AEHR', '2 Day long', 'Second Day Play', NULL, NULL, NULL, '60', 'https://www.tradingview.com/x/cvgoOjx3/', '["AEHR"]', 'Gap Up, Breakout, Trend Continuation, Second Day, Earnings, Offering, All Time High, Market Weak', NULL, NULL, '2026-04-09 17:12:29.594+00', '2026-04-09 17:24:17.134+00', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('27', 'Earnings Gap and Go', NULL, 'Gap', 'Stock gaps 3%+ after earnings, strong guidance, premarket volume 2M+', 'Check float size, RVOL at entry, first resistance identified', 'Best performance on tech earnings - Mega cap bias', '8', NULL, NULL, NULL, NULL, NULL, '2026-04-09 10:30:06.853+00', '2026-04-09 23:38:23.849+00', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('116', 'Multi-Day Breakout — Weekly Range Expansion', 'Swing Trading Setups', 'Breakout', 'Stock breaks out of a weekly/monthly range on catalyst. Hold for multi-day measured move. Wider stops, bigger targets.', '- Tight weekly range (Bollinger Bands squeezing)\n- Breakout on catalyst with volume >2x average\n- Close above range high (weekly candle)\n- Entry on pullback to breakout level\n- Stop below breakout level (former resistance = new support)\n- Target: measured move (range height added to breakout)\n- Hold time: 3-15 days', 'Weekly range breakouts capture larger moves than intraday trades. The tight range = low volatility, which precedes high volatility (regime change). Best combined with fundamental catalyst.', '76', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:54:49.547+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('17', 'Red to Green Move', 'Intraday Momentum', 'Reversal', 'Акция открылась red (ниже yesterday close)\nНет negative catalyst — продажа на общем рынке или sector rotation\nНачинает recovery с volume build\nReclaims yesterday close (red to green)\nStrong relative strength vs SPY', '- No company-specific bad news\n- Pre-market selling was sector/market-wide\n- Recovery on increasing volume\n- Break above yesterday close\n- Relative strength vs SPY positive\n- Entry: first pullback after R2G move\n- Stop: below the red-to-green level\n- Target: prior day high or VWAP from prior day', 'Red to Green — сигнал институционального buying. Кто-то считает цену attractive и набирает позицию.\n\nСамые сильные R2G moves происходят в первый час торгов. Если R2G происходит после 11 AM — менее надёжно.\n\nTrack: крупные tech names (AAPL, MSFT, GOOGL) часто показывают R2G в дни market weakness.', '77', NULL, NULL, 'reversal, red-to-green, relative-strength', NULL, NULL, '2026-04-09 10:30:06.853+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('18', 'VWAP Reclaim — Mean Reversion Long', 'Intraday Momentum', 'Reversal', 'Акция упала ниже VWAP утром на weak selling (low volume)\nНачинает формировать higher lows ниже VWAP\nVolume pick up на reclaim candle\nОбщий рынок (SPY) стабилен или растёт\nАкция имеет дневной uptrend (выше 20 SMA daily)', '- Stock pulled back to/below VWAP on declining volume\n- Higher lows forming (ascending triangle pattern)\n- Volume increase on reclaim candle\n- SPY not tanking\n- Daily trend is up (above 20 SMA)\n- Entry: break above VWAP with volume\n- Stop: below last higher low\n- Target: HOD retest', 'Mean reversion к VWAP — один из самых reliable сетапов. Работает когда selling exhaustion очевиден (volume dry up below VWAP).\n\nЛучше всего работает 10:30-11:30 AM ET после утренней волатильности.\n\nНе торговать если акция имеет negative catalyst (earnings miss, downgrade). Только для технических pullback.', '80', NULL, NULL, 'vwap, mean-reversion, long, reliable', NULL, NULL, '2026-04-09 10:30:06.853+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('127', 'Max Loss Day Rule — Circuit Breaker', 'Position Management', 'Другой', 'Hard daily loss limit. When reached, STOP TRADING. No exceptions. This is the most important risk management rule.', '- Set max daily loss (e.g., $500 or 2% of account)\n- Track P&L in real-time\n- At 50% of max loss: reduce size by half\n- At 75% of max loss: only A+ setups\n- At 100% of max loss: STOP. Walk away.\n- Review losing trades end of day\n- NO revenge trading\n- Reset next day fresh', 'The max loss day rule is NON-NEGOTIABLE. Every prop firm enforces this. Without it, one bad day can destroy a month of profits. SMB Capital says: ''Live to trade another day.'' The market will be there tomorrow.', '95', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:54:50.017+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('126', 'Scaling Out — Tiered Profit Taking', 'Position Management', 'Другой', 'Instead of all-or-nothing exits, scale out in tiers. Take 1/3 at first target, 1/3 at second, trail the rest.', '- Before entry: define 3 target levels\n- Target 1 (1R): take 1/3 off, move stop to breakeven\n- Target 2 (2R): take 1/3 off, trail stop\n- Target 3 (3R+): trail remaining 1/3 with tight stop\n- If stop hits before T1: full loss (acceptable)\n- Result: winners are bigger, losers are controlled\n- Track average R-multiple', 'Scaling out is a risk management technique that ensures you capture profits while keeping upside potential. The psychology: taking partial profits reduces the urge to close the entire position too early.', '85', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:54:49.974+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('16', 'Earnings Gap Up — First Pullback Long', 'SMB Capital - Earnings Plays', 'Earnings Gap Up', 'Gap up >5% на отчётности с beat по EPS и revenue\nОбъём premarket >500K shares\nКлючевые уровни: вчерашний high, pre-market high, whole/half dollars\nКатализатор чистый — guidance raised или beat >10%\nНет значимого сопротивления в первые $2-3 от открытия', '- EPS beat >5%\n- Revenue beat >3%\n- Guidance raised или не снижен\n- Premarket volume >500K\n- Gap >5% от close\n- Float <100M (идеально <30M)\n- Нет earnings peer в тот же день\n- Risk/Reward минимум 3:1\n- Стоп под VWAP или low первого 5-мин бара', 'SMB Capital core setup. Ждём первый откат к VWAP или rising 9 EMA на 1-мин после opening drive. Вход на hold VWAP с тейком на новый HOD. Ключ — скорость recovery после pullback. Если recovery медленная (>3 мин), пропускаем.\n\nЛучшие дни: вторник-четверг. Избегать в дни FOMC/CPI.\n\nTrades to study: CELH earnings Aug 2023, SMCI earnings Jan 2024, ONON earnings multiple.', '90', 'https://www.tradingview.com/x/ml9Ftk5B/', '["AEHR\\nGap up: +8 %\\nVokume: 500 k\\nПробила все ключевые уровни: вчерашний high, pre-market high\\nEPS = 28,5 %\\nНа открытии провалилась вниз на 2.5 поинта"]', 'earnings, gap-up, momentum, A+', NULL, NULL, '2026-04-09 10:30:06.853+00', '2026-04-10 17:30:44+00', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('92', 'Max Loss Day Rule — Circuit Breaker', 'Trillium - Position Management', 'Другой', 'Hard daily loss limit. When reached, STOP TRADING. No exceptions. This is the most important risk management rule.', '- Set max daily loss (e.g., $500 or 2% of account)\n- Track P&L in real-time\n- At 50% of max loss: reduce size by half\n- At 75% of max loss: only A+ setups\n- At 100% of max loss: STOP. Walk away.\n- Review losing trades end of day\n- NO revenge trading\n- Reset next day fresh', 'The max loss day rule is NON-NEGOTIABLE. Every prop firm enforces this. Without it, one bad day can destroy a month of profits. SMB Capital says: ''Live to trade another day.'' The market will be there tomorrow.', '95', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:43:21.707+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('91', 'Scaling Out — Tiered Profit Taking', 'Trillium - Position Management', 'Другой', 'Instead of all-or-nothing exits, scale out in tiers. Take 1/3 at first target, 1/3 at second, trail the rest.', '- Before entry: define 3 target levels\n- Target 1 (1R): take 1/3 off, move stop to breakeven\n- Target 2 (2R): take 1/3 off, trail stop\n- Target 3 (3R+): trail remaining 1/3 with tight stop\n- If stop hits before T1: full loss (acceptable)\n- Result: winners are bigger, losers are controlled\n- Track average R-multiple', 'Scaling out is a risk management technique that ensures you capture profits while keeping upside potential. The psychology: taking partial profits reduces the urge to close the entire position too early.', '85', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:43:21.668+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('90', 'Dollar Cost Into Winner — Pyramiding', 'Trillium - Position Management', 'Другой', 'When trade is working, add to the position (pyramid) at predetermined levels. Maximize winners, don''t just take profit.', '- Initial entry at planned level (full or partial)\n- First add: after breakout confirms (price + volume)\n- Second add: on first pullback that holds\n- Each add is smaller than the previous\n- Move stop to breakeven after first add\n- Trail stop to lock in profits on adds\n- Never add to losers\n- Max position: 3 tiers', 'Pyramiding into winners is how prop traders maximize their best trades. SMB calls this ''pressing your winners.'' The key: each add must be smaller, and the stop must move up. Never average down — that''s the opposite of this strategy.', '80', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:43:21.629+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('89', 'CPI / Jobs Report — Morning Gap Framework', 'SMB Capital - Macro & Sector Plays', 'Другой', 'Major economic data (CPI, NFP, PPI) released at 8:30 AM ET. Creates significant gaps. Trade the gap framework after open.', '- Note data release at 8:30 AM (pre-market)\n- Calculate gap vs expectations\n- If data better than expected = bullish gap (usually)\n- If data worse = bearish gap\n- Wait for market open, don''t pre-market trade\n- Apply Gap and Go or Gap Fill framework\n- Sector impact: CPI → tech/growth, Jobs → financials\n- Reduce size on macro days', 'Macro data days create the biggest moves because they affect ALL stocks simultaneously. CPI and jobs data move the entire market. Key: don''t trade the data, trade the reaction to the data. The same CPI number can be bullish or bearish depending on context.', '67', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:43:21.59+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('88', 'Fed Day / FOMC — 2:00 PM Reversal', 'SMB Capital - Macro & Sector Plays', 'Другой', 'FOMC announcement at 2:00 PM ET. Initial move often reverses. Wait for the ''whipsaw'' and trade the real direction.', '- No new positions before 2:00 PM on FOMC day\n- Note initial reaction direction at 2:00 PM\n- Wait 15-30 minutes for the ''whipsaw''\n- If initial move reverses = trade the reversal\n- If initial move continues with volume = trade continuation\n- Reduce size (FOMC = volatile)\n- Stop tight (FOMC moves are fast)\n- Close all FOMC trades by end of day', 'FOMC days have a well-known pattern: initial spike at 2:00 PM, then reversal, then the ''real'' move. The initial reaction is often wrong because algorithms react to headlines before the full statement is analyzed. Patience is key.', '62', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:43:21.55+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('87', 'Sector Rotation — Follow the Money', 'SMB Capital - Macro & Sector Plays', 'Другой', 'Money rotates between sectors based on economic cycle. Identify which sectors are receiving inflows and trade the leaders.', '- Monitor sector ETF relative performance (XLF, XLE, XLK, etc.)\n- Identify sector showing 3+ days of outperformance\n- Find leading stocks within that sector\n- Entry on pullback in the leading stock\n- Confirm with sector ETF still trending\n- Stop if sector rotation reverses\n- Target: sector trend continuation', 'Sector rotation is driven by institutional portfolio rebalancing. When the economy shifts, trillions of dollars rotate. Early identification = riding the institutional wave. Track XL_ ETFs daily for rotation signals.', '72', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:43:21.511+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('86', 'Earnings Range Anticipation — Straddle Alternative', 'SMB Capital - Earnings Plays', 'Pre-Earnings Run', 'Anticipate the earnings range based on implied move. Trade the break of that range rather than guessing direction.', '- Calculate expected move from options (straddle price)\n- Mark expected range (close +/- expected move)\n- After earnings: if price exceeds expected range = continuation\n- If price within expected range = mean reversion to close\n- Entry on confirmation of scenario\n- Stop based on expected range boundary\n- Target: 1.5x expected move (if exceeded) or prior close (if within)', 'Instead of guessing earnings direction, this framework uses the options market''s expected move as a roadmap. When the actual move exceeds expectations, momentum is real. When it stays within, the move is priced in.', '50', NULL, '[""]', NULL, NULL, NULL, '2026-04-09 23:43:21.471+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('85', 'Post-Earnings Drift (PEAD) — Follow Surprise', 'SMB Capital - Earnings Plays', 'Post-Earnings Continuation', 'After earnings surprise, stock continues drifting in the direction of the surprise for days/weeks. Trade the drift, not the gap.', '- Significant earnings surprise (>10% above/below estimates)\n- Initial gap confirmed by volume\n- Wait for first pullback (don''t chase the gap)\n- Entry on pullback in direction of surprise\n- Positive surprise: long pullback to VWAP/21EMA\n- Negative surprise: short bounce to VWAP/21EMA\n- Hold: 5-20 days\n- Trail stop using 8 EMA daily', 'Post-Earnings Announcement Drift (PEAD) is one of the most well-documented anomalies in finance. Studies show stocks continue moving in the direction of the earnings surprise for 60+ days. The market underreacts to earnings surprises.', '74', NULL, '[""]', NULL, NULL, NULL, '2026-04-09 23:43:21.432+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('84', 'Earnings Whisper — Pre-Earnings Position', 'SMB Capital - Earnings Plays', 'Pre-Earnings Run', 'Accumulate position before earnings when technical setup + whisper numbers suggest upside surprise. Small size for binary risk.', '- Earnings within 1-3 days\n- Technical setup bullish (above MAs, tight range)\n- Options IV < historical norm (cheap options)\n- Whisper number higher than consensus\n- Revenue growth trend positive\n- Entry: small position (25-50% normal size)\n- Define max loss BEFORE entry\n- Exit plan for both scenarios', 'Pre-earnings positions are high-risk binary trades. SMB teaches: if you trade earnings, use reduced size and define your max loss before entry. The best risk/reward comes when options IV is below average — you''re getting paid less for the uncertainty.', '58', NULL, '[""]', NULL, NULL, NULL, '2026-04-09 23:43:21.392+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('83', 'Fibonacci Retracement — Measured Pullback', 'SMB Capital — Swing Setups', 'Breakout', 'Stock in trend pulls back to key Fibonacci level (38.2%, 50%, 61.8%). Enter at Fib level with stop below next Fib.', '- Identify clear trend (impulse move)\n- Draw Fibonacci from swing low to swing high (uptrend)\n- Wait for pullback to 38.2%, 50%, or 61.8% level\n- Look for reversal candle at Fib level\n- Volume should decrease on pullback\n- Entry on bounce from Fib with volume\n- Stop below next Fib level\n- Target: retest of prior high or 1.618 extension', 'Fibonacci levels are self-fulfilling because so many traders use them. The 61.8% level is especially powerful — it''s the ''golden ratio'' pullback. If price holds 61.8%, the trend is likely intact. Below 78.6% = trend likely failed.', '71', NULL, '[""]', NULL, NULL, NULL, '2026-04-09 23:43:21.352+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('82', 'Moving Average Crossover — Trend Change', 'SMB Capital — Swing Setups', 'Другой', '8/21 EMA crossover on daily chart signals trend change. Enter in direction of the cross with swing time frame.', '- 8 EMA crosses above 21 EMA = bullish\n- 8 EMA crosses below 21 EMA = bearish\n- Volume confirms crossover\n- Wait for pullback to 8 EMA after cross\n- Entry on bounce off 8 EMA in crossover direction\n- Stop: below 21 EMA\n- Target: prior swing high/low or Fibonacci extension\n- Hold: 5-20 days', 'EMA crossovers lag by nature but filter noise. The 8/21 combo captures trend changes faster than 50/200. Best used as a trend filter — take only long setups when 8>21, short setups when 8<21.', '63', NULL, '[""]', NULL, NULL, NULL, '2026-04-09 23:43:21.312+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('81', 'Multi-Day Breakout — Weekly Range Expansion', 'SMB Capital — Swing Setups', 'Breakout', 'Stock breaks out of a weekly/monthly range on catalyst. Hold for multi-day measured move. Wider stops, bigger targets.', '- Tight weekly range (Bollinger Bands squeezing)\n- Breakout on catalyst with volume >2x average\n- Close above range high (weekly candle)\n- Entry on pullback to breakout level\n- Stop below breakout level (former resistance = new support)\n- Target: measured move (range height added to breakout)\n- Hold time: 3-15 days', 'Weekly range breakouts capture larger moves than intraday trades. The tight range = low volatility, which precedes high volatility (regime change). Best combined with fundamental catalyst.', '76', NULL, '[""]', NULL, NULL, NULL, '2026-04-09 23:43:21.273+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('80', 'Exhaustion Gap — Reversal Signal', 'SMB Capital — Gap Plays', 'Gap', 'After an extended multi-day move, a final gap in the trend direction signals exhaustion. Trade the reversal.', '- Stock has moved >20% in one direction over 3-5 days\n- Final gap in the same direction (up gap after rally, down gap after selloff)\n- Volume highest of the entire move\n- Intraday reversal candle forms (shooting star, doji)\n- Entry on reversal confirmation\n- Stop above/below exhaustion gap extreme\n- Target: 38-50% retrace of entire move', 'Exhaustion gaps are one of the most reliable reversal signals in technical analysis. They represent the last burst of momentum before the trend reverses. Key identifier: the gap comes AFTER a multi-day move, not at the beginning.', '65', NULL, '[""]', NULL, NULL, NULL, '2026-04-09 23:43:21.233+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('79', 'Gap and Trap — False Breakout', 'SMB Capital — Gap Plays', 'Gap', 'Stock gaps up through resistance but immediately sells off. The gap traps breakout buyers. Short the trapped longs as they panic.', '- Stock gaps above key resistance level\n- First 15 minutes: selling pressure emerges\n- Stock falls back below resistance (now support becomes resistance)\n- Trapped longs begin to panic sell\n- Entry short on break below gap low or key level\n- Volume increases on the reversal\n- Stop above gap high\n- Target: prior support or gap fill', 'Gap and Trap is the opposite of Gap and Go. It works because breakout buyers get trapped when the gap fails. Their stop-loss selling accelerates the move down. Best when the gap is on weak catalyst or into major resistance.', '72', NULL, '[""]', NULL, NULL, NULL, '2026-04-09 23:43:21.193+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('78', 'Gap Fill — Statistical Edge', 'SMB Capital — Gap Plays', 'Gap', 'Most gaps fill within 1-3 days (statistical tendency). Trade the gap fill when conditions support mean reversion back to prior close.', '- Gap without strong catalyst (earnings, FDA excluded)\n- Gap size < 5% (large gaps less likely to fill same day)\n- Pre-market volume normal (not elevated)\n- If gap up: short toward prior close\n- If gap down: long toward prior close\n- Entry after first 15 min (avoid opening volatility)\n- Stop beyond gap extreme\n- Target: prior day close (full fill)', 'Statistical studies show ~70% of gaps eventually fill. However, catalyst-driven gaps (earnings, FDA) fill less often. Best gap fill trades are on ''nothing'' gaps — gap on no real news, just overnight drift.', '70', NULL, '[""]', NULL, NULL, NULL, '2026-04-09 23:43:21.154+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('77', 'Pairs Trade — Relative Value', 'Jane Street - Mean Reversion Plays', 'Другой', 'Two correlated stocks diverge. Long the underperformer, short the outperformer. Profit when the spread reverts to mean.', '- Identify correlated pair (same sector, similar business)\n- Calculate historical spread (ratio or price difference)\n- Wait for spread to reach 2+ StdDev from mean\n- Long the laggard, short the leader (equal dollar amounts)\n- Monitor correlation — if it breaks, exit\n- Target: spread returns to mean\n- Max hold: 5-10 days', 'Pairs trading is market-neutral — you profit from the relative move, not the absolute direction. Classic pairs: XOM/CVX, GOOGL/META, JPM/BAC. Risk: the correlation can break permanently (structural change).', '75', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:43:21.114+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('76', 'Rubber Band Snap — Extended Stock Reversal', 'Jane Street - Mean Reversion Plays', 'Reversal', 'Stock stretched far from VWAP or moving average like a rubber band. Trade the snap-back to the mean when momentum exhausts.', '- Stock >2% from VWAP (intraday) or >5% from 20MA (daily)\n- Momentum indicators showing divergence\n- Volume decreasing on the extension\n- Candle pattern showing reversal (doji, hammer, engulfing)\n- Entry on reversal confirmation\n- Stop beyond the extreme\n- Target: VWAP or moving average', 'The rubber band analogy: the further a stock stretches from its mean, the more energy is stored for the snap-back. Works best when the extension is on declining volume — showing exhaustion rather than genuine trend.', '68', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:43:21.074+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('75', 'Mean Reversion — Oversold Bounce', 'Jane Street - Mean Reversion Plays', 'Reversal', 'Stock drops >3 standard deviations from its mean (20-day MA). Statistical probability favors a bounce. Long the oversold condition.', '- Stock >3 StdDev below 20-day MA\n- RSI < 20 on daily chart\n- No fundamental catalyst for further downside\n- Volume exhaustion (decreasing on sell-off)\n- Entry on first green candle after selling exhaustion\n- Stop below recent low\n- Target: 20-day MA (mean)', 'Mean reversion works because extreme moves are statistically unsustainable. However, key filter: avoid stocks with ongoing fundamental deterioration (bankruptcy risk, fraud, etc.). Best on large-cap with temporary panic.', '72', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:43:21.035+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('74', 'Level 2 Spoofing Detection', 'Jane Street - Advanced Tape Reading', 'Другой', 'Detect spoofing on Level 2 — large orders that appear and disappear to manipulate price. Trade opposite the spoof direction.', '- Watch for large bid/ask orders that repeatedly cancel\n- Spoof orders usually >50K shares on illiquid stocks\n- Note if price moves toward the spoof, then spoof is removed\n- Real orders get filled, spoof orders get cancelled\n- If large bid keeps disappearing = fake support = bearish\n- If large ask keeps disappearing = fake resistance = bullish\n- Use tape confirmation before entry', 'Spoofing is illegal but still occurs, especially on small/mid cap stocks. Recognizing it gives you an edge because you understand which levels are real and which are fake. Key: real orders absorb volume, spoof orders run.', '60', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:43:20.995+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('73', 'Dark Pool Print — Hidden Liquidity', 'Jane Street - Advanced Tape Reading', 'Другой', 'Unusually large dark pool prints signal institutional interest. Trade in direction of the largest prints when they cluster at a price level.', '- Monitor dark pool print data (Finra ADF, TRF)\n- Look for prints >100K shares\n- Note price level where prints cluster\n- If prints at/above ask = bullish\n- If prints at/below bid = bearish\n- Use as confirmation, not primary signal\n- Combine with chart pattern for entry', 'Dark pools account for ~40% of US equity volume. Large institutional orders often execute there to avoid market impact. When you can see these prints, you''re seeing what smart money is doing.', '65', NULL, NULL, 'Dark Pool Print,Block Trade Follow,Tape Reading Entry,Dark Pool Level,Dark Pool Volume', NULL, NULL, '2026-04-09 23:43:20.956+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('72', 'Tape Reading — Order Flow Entry', 'Jane Street - Advanced Tape Reading', 'Другой', 'Read Level 2 / Time & Sales to identify institutional activity. Large prints, hidden orders, and bid/ask dynamics reveal intent.', '- Watch Time & Sales for large prints (>10K shares)\n- Note bid/ask size imbalances on Level 2\n- Look for iceberg orders (repeated same-size prints)\n- Identify institutional accumulation vs distribution\n- Entry when tape confirms your directional bias\n- Stop if tape reading thesis is invalidated', 'Tape reading is the original edge. Before charts, traders read the tape. Large prints at the ask = buying pressure. Large prints at the bid = selling pressure. SMB Capital considers tape reading a core skill.', '78', NULL, NULL, 'Tape Reading Entry,Level 2 Entry,Dark Pool Print,Block Trade Follow,High Relative Volume', NULL, NULL, '2026-04-09 23:43:20.916+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('71', 'Overnight Hold — Swing Catalyst', 'Trillium - Pre-Market & After Hours', 'Другой', 'Hold position overnight when catalyst supports multi-day move. Reduce size for overnight risk. Set hard stop.', '- Catalyst supports multi-day move (earnings beat, FDA, M&A)\n- Reduce position to 50% of intraday size\n- Set hard stop (worst-case exit level)\n- Calculate overnight gap risk\n- Check after-hours liquidity\n- Set pre-market alert for review\n- Re-evaluate at next open', 'Overnight holds add gap risk but capture multi-day moves. Key rule: if you wouldn''t enter the position fresh at the close, don''t hold it overnight. Always reduce size.', '55', NULL, NULL, 'Swing Hold,Overnight Hold Gap,Multi-Day Momentum,Earnings Beat,FDA Approval', NULL, NULL, '2026-04-09 23:43:20.877+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('70', 'After Hours Earnings React — Next Day Prep', 'Trillium - Pre-Market & After Hours', 'Другой', 'Stock reports earnings after hours. Analyze reaction, prepare next-day game plan based on after-hours price action.', '- Note earnings results vs expectations\n- Watch after-hours price reaction\n- Identify key AH levels (high, low, close)\n- Check options implied move vs actual\n- Prepare bull/bear scenario for next day\n- Set pre-market alerts', 'After-hours reaction to earnings often sets the tone for the next trading day. Preparing the night before gives you a significant edge over traders who react in real-time.', '70', NULL, NULL, 'Earnings Gap Up,Earnings Gap Down,Second Day Play,After Hours,Earnings Beat,Earnings Miss', NULL, NULL, '2026-04-09 23:43:20.837+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('69', 'Pre-Market Gap Scan — Watchlist Build', 'Trillium - Pre-Market & After Hours', 'Другой', 'Before market open (7:00-9:30 AM ET). Scan for stocks gapping >4% on catalyst. Build watchlist with levels, plan entries.', '- Scan at 7:00 AM for gaps >4%\n- Check catalyst (earnings, news, upgrade/downgrade)\n- Note pre-market volume (>500K = in play)\n- Mark key levels: PM high, PM low, prior day close\n- Calculate ATR for position sizing\n- Rank top 3-5 stocks by catalyst quality\n- Set alerts at key levels', 'The most important 30 minutes of the day happens before the market opens. Every successful prop trader starts with a thorough pre-market scan. This framework ensures you''re prepared, not reactive.', '85', NULL, NULL, 'Gap Up,Gap Down,Premarket,Premarket High,Premarket Low,High Relative Volume', NULL, NULL, '2026-04-09 23:43:20.798+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('68', 'MOC + Options Expiration — Pin Risk Play', 'Trillium - MOC / Closing Auction', 'Другой', 'On options expiration (monthly/weekly), stocks tend to ''pin'' to strike prices with maximum open interest. Trade the pin into the close.', '- Identify max pain / highest OI strike price\n- After 2:00 PM on OPEX day, monitor price vs strike\n- If stock near high-OI strike, expect pinning action\n- Trade toward the pin strike (mean reversion to strike)\n- MOC order at the pin strike if profitable\n- Size small — pinning is not guaranteed\n- Works best on large-cap with high options volume\n- Close all positions at market close', 'Options expiration pinning occurs because market makers hedge their delta by buying/selling stock. As options expire, this hedging creates mean-reversion toward the highest open interest strike. This effect is strongest in the last 2 hours of OPEX day.', '62', NULL, NULL, 'MOC Imbalance,Closing Cross Play,Imbalance,OPEX Day,Last Hour,Round Number', NULL, NULL, '2026-04-09 23:43:20.676+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('67', 'MOC Fade — Closing Reversal', 'Trillium - MOC / Closing Auction', 'Другой', 'After an extreme closing imbalance pushes price, the next morning often sees a reversal. Fade the closing auction move at next open.', '- Large closing imbalance pushed price >0.5% in last 15 min\n- The move was mechanical (rebalance) not fundamental\n- Next day: fade the closing move direction\n- Entry: at open or first 15 min of next day\n- Target: prior day''s 3:45 PM price (pre-imbalance level)\n- Stop: beyond closing price\n- Works best on quarterly rebalance days\n- Avoid if fundamental catalyst exists', 'Closing imbalances are mechanical — index funds MUST buy or sell regardless of price. This creates artificial moves that often reverse the next morning when the forced buying/selling is done. Key: only fade mechanical moves, not fundamental ones.', '60', NULL, NULL, 'MOC Imbalance,Closing Cross Play,Fade Trade,Reversal,Last Hour,Power Hour', NULL, NULL, '2026-04-09 23:43:20.637+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('66', 'MOC Imbalance — Closing Auction Play', 'Trillium - MOC / Closing Auction', 'Другой', 'NYSE publishes closing imbalance data at 3:45 PM. Large MOC imbalances create predictable price moves into the close. Trade the last 15 minutes.', '- Check closing imbalance at 3:45 PM ET\n- Buy imbalance > 500K shares = bullish into close\n- Sell imbalance > 500K shares = bearish into close\n- Entry at 3:45-3:50 PM in direction of imbalance\n- Price typically moves toward imbalance direction\n- Quick trade: entry 3:45, exit at close or MOC\n- No overnight hold required\n- Best on index rebalance / options expiration days', 'Closing imbalances are the most predictable short-term trades in the market. Index funds, ETFs, and institutional rebalancing create massive order imbalances at the close. On rebalancing days, these can be >$2B. The price MUST adjust to fill these orders.', '73', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:43:20.596+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('65', 'MOC — Market On Close Order', 'Trillium - MOC / Closing Auction', 'Другой', 'Use MOC (Market-On-Close) order to participate in the NYSE closing auction. Capture the closing print for next-day gap positioning.', '- MOC orders must be submitted by 3:45 PM ET (NYSE) or 3:50 PM (NASDAQ)\n- Determine direction based on day''s trend (above/below VWAP)\n- Size: 50% of normal for overnight risk\n- MOC guarantees fill at official closing price\n- Cannot cancel after 3:45 PM deadline\n- Best for next-day catalyst plays (earnings AH, overnight events)\n- Review closing imbalance data at 3:45 PM\n- Set overnight stop-loss alert', 'MOC orders are used by institutions to execute at the closing price — the most important price of the day. For prop traders, MOC is useful when you want to hold overnight and want the best closing price without chasing.', '76', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:43:20.557+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('64', 'IMBX + VWAP Confirmation', 'Jane Street - Imbalance (IMBX) Strategies', 'Imbalance', 'Combine imbalance data with VWAP direction. When opening imbalance aligns with VWAP trend (stock opens above/below VWAP in same direction as imbalance), the signal is strongest.', '- Buy imbalance + stock above developing VWAP = strong long\n- Sell imbalance + stock below developing VWAP = strong short\n- Entry on first pullback to VWAP after open\n- Volume must confirm direction\n- Contradictory signals (buy imbalance but below VWAP) = no trade\n- Stop: VWAP cross\n- Target: prior day level or measured move\n- This is a high-probability A+ setup when aligned', 'Combining two institutional signals (imbalance + VWAP) creates a high-probability setup. Institutions use both VWAP and auction data. When they agree, you''re aligned with smart money. When they contradict, stay flat.', '80', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:43:20.517+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('63', 'IMBX Fade — Imbalance Reversal', 'Jane Street - Imbalance (IMBX) Strategies', 'Imbalance', 'When opening imbalance is extreme but reverses by 9:28 AM, the initial move often reverses. Fade the expected direction.', '- Large imbalance at 9:20 (>1M shares one direction)\n- By 9:28 AM imbalance reduces significantly or flips\n- This signals the imbalance was absorbed / crossed\n- Trade opposite the original imbalance direction\n- Wait for open, then entry on reversal candle\n- Small size (counter-trend play)\n- Stop tight — opposite side of opening range\n- Target: VWAP', 'Imbalance fades are advanced plays. When a large buy imbalance at 9:20 gets paired off by 9:28, it means the selling interest absorbed the demand. The opening may still pop up, but it quickly reverses. This is a trap for imbalance-only traders.', '58', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:43:20.477+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('62', 'IMBX — Opening Imbalance Short', 'Jane Street - Imbalance (IMBX) Strategies', 'Imbalance', 'Significant sell imbalance (IMBX > 500K shares on sell side) at 9:20 AM. Strong selling pressure expected at open. Short into the imbalance.', '- Sell imbalance > 500K shares at 9:20+ AM\n- Confirm negative catalyst (earnings miss, downgrade)\n- Entry via OPG short or first bounce after open\n- Imbalance should be consistent and growing\n- Watch 9:28 AM final imbalance (most reliable)\n- Stop: if imbalance reverses significantly\n- Target: morning low or gap fill\n- Close by midday if not working', 'Sell imbalances create supply/demand asymmetry at the open. Institutions are net sellers and the opening price adjusts down. Key: the 9:28 AM imbalance is the most reliable — earlier readings can flip.', '74', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:43:20.438+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('61', 'IMBX — Opening Imbalance Long', 'Jane Street - Imbalance (IMBX) Strategies', 'Imbalance', 'NYSE/NASDAQ publish order imbalance data at 9:20 AM. Significant buy imbalance (IMBX > 500K shares) signals strong opening demand. Long into the imbalance.', '- Check imbalance data starting at 9:20 AM\n- Buy imbalance > 500K shares = significant\n- Confirm catalyst supports the direction\n- Entry via OPG order or first pullback after open\n- Imbalance should be consistent (not flipping)\n- Watch for paired-off vs total imbalance ratio\n- Stop: if imbalance reverses or VWAP breaks\n- Target: morning high or prior resistance', 'Order imbalance data is public and published by exchanges. A large buy imbalance means there are significantly more buy orders than sell orders for the open. This creates upward pressure on the opening price. Prop firms monitor this data religiously.', '74', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:43:20.398+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('42', 'Second Day Play — Momentum Continuation', 'SMB Capital — Gap Plays', 'Second Day Play', 'Stock had a big move Day 1 (earnings, news, IPO). Day 2 continuation trade — long above Day 1 high or short below Day 1 low.', '- Day 1 move was >10% on catalyst\n- Pre-market shows continuation interest\n- Entry above Day 1 high (long) or below Day 1 low (short)\n- Volume confirmation needed\n- Stop: Day 1 close or VWAP\n- Target: measured move from Day 1 range', 'Second Day Play is one of SMB''s signature setups. The idea: momentum from Day 1 carries into Day 2. Best when the catalyst is fundamental (earnings, FDA) rather than technical.', '70', NULL, NULL, 'Second Day Play,Trend Continuation,Breakout,Gap Up,HOD,Yesterday High,High Relative Volume', NULL, NULL, '2026-04-09 23:34:22.251+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('60', 'OPG Momentum — Opening Auction Breakout', 'Trillium - OPG / Auction Plays', 'OPG', 'Use OPG to ride momentum when opening auction price will be significantly different from prior close. Follow the smart money flow.', '- Pre-market shows strong directional bias\n- Imbalance data (if available) confirms direction\n- Submit OPG in direction of momentum\n- Immediately set stop after fill\n- Target 1: first 5-min range extreme\n- Target 2: VWAP or prior resistance/support\n- Scale out in thirds\n- Best on In Play stocks with catalyst', 'OPG momentum captures the institutional order flow at the open. When there''s a clear imbalance (more buy than sell orders), the opening price adjusts up and the momentum continues. Getting in at the auction = best possible entry.', '72', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:43:20.359+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('59', 'OPG Gap Fade — Auction Reversal', 'Trillium - OPG / Auction Plays', 'OPG', 'Stock gaps significantly on weak catalyst. OPG order to fade the gap — enter opposite direction at the open, expecting gap fill.', '- Gap >3% but catalyst is weak or already priced in\n- Pre-market volume is moderate (not extreme)\n- No institutional upgrades/downgrades\n- Submit OPG order to fade gap direction\n- Size: 25-50% of normal\n- Target: gap fill (prior close)\n- Stop: beyond gap extreme +0.5%\n- Time limit: close by lunch if not working', 'Fading gaps at the open is risky but statistically favorable when the catalyst is weak. The OPG order ensures you get the exact opening price. Key: only fade gaps with no fundamental reason. Earnings/FDA gaps should NOT be faded.', '68', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:43:20.319+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('58', 'OPG — Opening Price Guarantee Order', 'Trillium - OPG / Auction Plays', 'OPG', 'Use OPG (Market-On-Open) order to participate in the NYSE/NASDAQ opening auction. Capture the opening print when catalyst is clear overnight.', '- Strong overnight catalyst (earnings, news, upgrade)\n- Pre-market direction is clear and consistent\n- Submit OPG order before 9:28 AM ET\n- Size: 50% of normal (auction risk)\n- OPG executes only at the opening print\n- If no fill, order cancels automatically\n- Review fill vs pre-market price\n- Manage position from open', 'OPG orders guarantee you participate in the opening auction at the official opening price. This is how institutions enter positions. Advantage: no slippage from the open, you get the exact opening print. Best on gap days with clear catalyst.', '75', NULL, NULL, NULL, NULL, NULL, '2026-04-09 23:43:20.279+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('57', 'Power Hour Momentum — 3:00–4:00 PM', 'SMB Capital — Intraday Setups', 'Intraday Momentum', 'Last hour of trading (3:00-4:00 PM). Institutions execute large orders, creating momentum. Trade in direction of the day''s trend.', '- Identify day''s trend (above/below VWAP)\n- Wait until 3:00 PM\n- Look for volume increase (institutional activity)\n- Long if above VWAP all day, Short if below\n- Entry on pullback within the trend\n- Stop: VWAP cross\n- Target: close of day or trailing stop', 'Power hour is when institutions execute their remaining orders for the day. This creates volume and momentum. SMB teaches that the last hour often mirrors the first hour in terms of direction and opportunity.', '68', NULL, NULL, 'Intraday Momentum,VWAP Trend,Trend Continuation,Power Hour,Last Hour,VWAP', NULL, NULL, '2026-04-09 23:34:22.819+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('56', 'In Play Stock Framework — Отбор акций', 'SMB Capital — Frameworks', 'Другой', 'Framework for identifying ''In Play'' stocks — stocks that will have the most opportunity for day traders on a given day.', '- Fresh catalyst (earnings, FDA, news) within 24 hours\n- Gap > 4% (up or down)\n- Pre-market volume > 500K shares\n- Relative volume > 2x average\n- ATR > $2 (enough range to trade)\n- Float < 100M preferred\n- Not in a halt or pending news\n- Check sector (is the whole sector moving?)', 'The In Play framework is the foundation of SMB Capital''s methodology. Before trading any setup, the stock must be ''In Play'' — meaning it has a catalyst, volume, and range to create opportunity. Without In Play status, setups have much lower probability.', '90', NULL, NULL, 'Gap Up,Gap Down,High Relative Volume,Volume Spike,Breaking News,Earnings Beat', NULL, NULL, '2026-04-09 23:34:22.778+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('55', 'News Fade — Sell/Short the News', 'SMB Capital — Reversal Setups', 'Reversal', 'Stock spikes on news but the news is already priced in or overhyped. Fade the initial move as it reverses.', '- News event causes spike (upgrade, product launch, partnership)\n- Assess if news is truly new or already expected\n- Wait for first signs of reversal (red candle, volume shift)\n- Entry on break of initial spike candle low\n- Stop above spike high\n- Target: pre-news price or VWAP', '''Buy the rumor, sell the news'' — one of the oldest market principles. SMB teaches to identify when news is already priced in by checking: pre-news price action, options activity, and whether the move is proportional to the catalyst.', '66', NULL, NULL, 'Fade Trade,News Spike Fade,Reversal,Short,Breaking News,Analyst Upgrade,VWAP', NULL, NULL, '2026-04-09 23:34:22.741+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('54', 'High of Day Break — Momentum Ignition', 'SMB Capital — Intraday Setups', 'Breakout', 'Stock consolidates near HOD then breaks to new highs. This ''momentum ignition'' triggers stops and algorithms, creating a powerful move.', '- Stock near HOD with tightening range\n- At least 2-3 tests of HOD level\n- Volume building on each test\n- Entry on break above HOD with volume surge\n- Stop below consolidation / last pullback low\n- Target: next resistance or measured move', 'HOD breaks are powerful because they trigger: 1) Buy stops from shorts, 2) Momentum algorithms, 3) Breakout traders. The combination creates a supply/demand imbalance that drives price higher quickly.', '73', NULL, NULL, 'Breakout,Momentum Ignition,HOD,Flat Top Breakout,Volume Spike,High Relative Volume,Trending Day', NULL, NULL, '2026-04-09 23:34:22.705+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('53', 'Dead Cat Bounce — Short the Recovery', 'SMB Capital — Short Setups', 'Reversal', 'Stock drops sharply on bad news (earnings miss, downgrade). A weak bounce follows. Short the failed bounce.', '- Stock dropped >10% on negative catalyst\n- Weak bounce: low volume, doesn''t reclaim VWAP\n- Bounce reaches resistance (prior support, moving average)\n- Entry on reversal from bounce high\n- Stop above bounce high\n- Target: retest of lows or new low', 'Dead cat bounces occur because: 1) Short covering, 2) Bottom fishers, 3) Algorithmic mean reversion. These bounces typically fail because the fundamental damage is real. SMB shorts these aggressively.', '68', NULL, NULL, 'Dead Cat Bounce,Reversal,Fade Trade,Short,Earnings Miss,Analyst Downgrade,VWAP,Daily Resistance', NULL, NULL, '2026-04-09 23:34:22.668+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('52', '9 EMA Daily — Swing Entry на Trend', 'SMB Capital — Swing Setups', 'Breakout', 'Stock in strong uptrend pulls back to 9 EMA on daily chart. This is the ''trend pullback'' entry for swing traders.', '- Stock in clear uptrend (higher highs, higher lows)\n- Pullback to 9 EMA daily (within 1-2% of EMA)\n- Volume decreases on pullback\n- Entry on bounce off 9 EMA with volume\n- Stop: below 9 EMA or recent swing low\n- Target: prior high or measured move\n- Hold time: 2-10 days', 'The 9 EMA daily is SMB''s favorite swing setup. It works because strong stocks rarely pull back more than 3-5 days before continuing. The 9 EMA captures this rhythm perfectly.', '74', NULL, NULL, 'Pullback Trade,Swing Hold,Trend Continuation,EMA9,Daily Support,Trending Day', NULL, NULL, '2026-04-09 23:34:22.631+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('51', 'Anchored VWAP — Earnings / IPO Level', 'SMB Capital — Intraday Setups', 'Breakout', 'Anchored VWAP from significant event (earnings, IPO, offering) acts as key support/resistance. Trade the reaction at this level.', '- Identify significant event date (earnings, IPO, offering)\n- Calculate anchored VWAP from that date\n- Wait for price to reach anchored VWAP level\n- Look for reaction (bounce or break)\n- Entry on confirmation of direction\n- Stop: other side of anchored VWAP\n- Target: next significant level', 'Anchored VWAP shows the average price paid by all participants since a significant event. Institutions track this level closely. It''s especially powerful from earnings dates and IPO dates.', '70', NULL, NULL, 'VWAP Bounce,VWAP Rejection,Breakout,Anchored VWAP,Earnings Beat,IPO Stock,Daily Support,Daily Resistance', NULL, NULL, '2026-04-09 23:34:22.594+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('50', 'Halt & Resume Play', 'SMB Capital — Intraday Setups', 'Другой', 'Stock gets halted (LULD halt or news halt). Trade the resume — either continuation or reversal depending on context.', '- Note halt type (LULD up/down, news pending)\n- During halt: assess catalyst, level 2, pre-halt momentum\n- On resume: wait 30 seconds for price discovery\n- If continuation: long above halt price (up halt) or short below (down halt)\n- If reversal: opposite direction after failed continuation\n- Use small size — halts = maximum volatility\n- Stop: opposite side of resume range', 'Halt resumes are some of the highest-volatility moments in trading. SMB teaches discipline: don''t place orders during halt, wait for resume, let price discover, then act. Many traders get destroyed by blindly buying/shorting halts.', '65', NULL, NULL, 'Halt & Resume,Breakout,Reversal,High Relative Volume,Volume Spike,High Volatility', NULL, NULL, '2026-04-09 23:34:22.548+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('49', 'Sympathy Play — Sector Follower', 'SMB Capital — Momentum Setups', 'Intraday Momentum', 'When a sector leader makes a big move, other stocks in the same sector often follow (sympathy move). Trade the follower.', '- Identify the sector leader making the move\n- Find related stocks in same sector/industry\n- Sympathy stock should have its own catalyst or setup\n- Entry on breakout or momentum confirmation\n- Don''t chase — wait for your setup\n- Stop based on the sympathy stock''s chart, not the leader\n- Target: proportional move to leader', 'Sympathy plays are a staple of prop trading. When NVDA moves, watch AMD, AVGO, MU. When one biotech gets FDA approval, watch similar pipeline companies. Key: the leader goes first, sympathies follow with a delay.', '60', NULL, NULL, 'Sympathy Play,Sector Rotation Play,Intraday Momentum,Breakout,Sector Leading,Sector Rotation', NULL, NULL, '2026-04-09 23:34:22.511+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('48', 'Short Squeeze Play', 'SMB Capital — Momentum Setups', 'Intraday Momentum', 'High short interest stock (>20%) gets a catalyst. Short sellers forced to cover, creating buying pressure and rapid price increase.', '- Short interest > 20% of float\n- Catalyst (earnings beat, news, upgrade)\n- Pre-market gap up with high volume\n- Entry on first pullback after initial squeeze\n- Monitor short interest data / borrow rates\n- Tight stop (if squeeze fails, reversal is sharp)\n- Target: prior resistance levels from weekly chart', 'Short squeezes are unpredictable. SMB teaches to trade them small and respect the volatility. The best squeezes happen when fundamental catalyst + high short interest + low float combine.', '55', NULL, NULL, 'Short Squeeze,Intraday Momentum,Breakout,High Short Interest (>20%),High Relative Volume,Volume Spike,Gap Up', NULL, NULL, '2026-04-09 23:34:22.475+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('47', 'Failed Follow Through — Bear Flag Short', 'SMB Capital — Short Setups', 'Reversal', 'Stock had a big move up but fails to follow through. Forms a bear flag (weak bounce on low volume). Short the breakdown of the flag.', '- Prior move up on Day 1\n- Day 2/3: weak bounce, low volume\n- Bear flag pattern forms (lower highs)\n- Entry on break below flag support\n- Volume increases on breakdown\n- Stop above flag high\n- Target: measured move down (flag pole)', 'Failed follow-through is the opposite of the Second Day Play. When momentum should continue but doesn''t, it''s a powerful reversal signal. SMB uses this as one of their primary short setups.', '73', NULL, NULL, 'Failed Follow Through,Bear Flag,Reversal,Dead Cat Bounce,Short,Yesterday High,Low Volume', NULL, NULL, '2026-04-09 23:34:22.437+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('46', 'Low Float Momentum — Float Rotation', 'SMB Capital — Intraday Setups', 'Intraday Momentum', 'Low float stock (<20M shares) with catalyst. When volume > float (float rotation), momentum can carry the stock much further than expected.', '- Float < 20M shares\n- Catalyst (earnings, news, FDA)\n- Volume approaching or exceeding float\n- Stock making new HOD with increasing volume\n- Entry on pullback or flag break\n- Small size (low float = volatile)\n- Stop: prior consolidation low', 'Float rotation = when the entire float has traded hands. At this point, there are no more ''trapped'' sellers and the stock can run much further. Key metric: volume/float ratio.', '60', NULL, NULL, 'Intraday Momentum,Runner,Breakout,Bull Flag,Low Float (<10M),Extremely Low Float (<2M),High Relative Volume,Volume Spike', NULL, NULL, '2026-04-09 23:34:22.4+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('45', 'Opening Range Breakout (ORB)', 'SMB Capital — Intraday Setups', 'Breakout', 'First 5/15/30 minute range establishes. Trade the breakout above the high or breakdown below the low of that range.', '- Define opening range (5min, 15min, or 30min)\n- Wait for range to complete\n- Long above range high / Short below range low\n- Volume must confirm breakout (> average)\n- Stop: opposite side of range or midpoint\n- Target: 1:1 then trail', 'ORB is a bread-and-butter SMB setup. The opening range captures the battle between buyers and sellers. When one side wins (breakout), the move can be powerful. Best on days with catalyst.', '72', NULL, NULL, 'ORB,ORB 5min,ORB 15min,Breakout,Opening Range High,Opening Range Low,First 15min,First 30min,Volume Spike', NULL, NULL, '2026-04-09 23:34:22.364+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('44', 'Parabolic Short — Extended Stock', 'SMB Capital — Short Setups', 'Reversal', 'Stock goes parabolic (vertical move up 30%+ intraday). Short the blow-off top when momentum exhausts.', '- Stock up >30% intraday on low/mid float\n- Parabolic arc visible on 1-min chart\n- Wait for first red candle after vertical move\n- Volume climax (highest volume candle of the day)\n- Entry on break of first red candle low\n- Stop above high of day\n- Target: VWAP or 50% retrace', 'High risk / high reward. SMB teaches strict rules: NEVER short into strength. Wait for the first crack. Use small size. The blow-off top often comes with a volume climax — that''s your signal.', '65', NULL, NULL, 'Parabolic Short,Blow-Off Top Short,Exhaustion Short,Reversal,HOD,Low Float (<10M),High Relative Volume,Volume Spike', NULL, NULL, '2026-04-09 23:34:22.327+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('43', 'VWAP Trend Trade — Intraday', 'SMB Capital — Intraday Setups', 'Intraday Momentum', 'Stock trends above/below VWAP all day. Trade pullbacks to VWAP in direction of the trend. Long if above, short if below.', '- Clear trend direction established by 10:00 AM\n- Stock respects VWAP as support (uptrend) or resistance (downtrend)\n- Entry on pullback to VWAP with volume dry-up\n- Stop: VWAP cross (close below for longs, above for shorts)\n- Trail stop using rising/falling VWAP', 'VWAP is the institutional benchmark. When a stock trends above VWAP, institutions are net buyers. When below, net sellers. This creates a self-reinforcing cycle.', '75', NULL, NULL, 'VWAP Trend,VWAP Bounce,VWAP Hold Long,Pullback Trade,Intraday Momentum,VWAP,Trending Day', NULL, NULL, '2026-04-09 23:34:22.289+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('41', 'IPO Day Trade — First Day Play', 'SMB Capital — IPO Plays', 'IPO Day Trade', 'First day of trading for IPO. Wait for opening range to establish (first 5-15 min), then trade the breakout or breakdown.', '- IPO with significant hype/demand\n- Wait for opening print and first range\n- Don''t trade first 5 minutes\n- Long above opening range high OR short below opening range low\n- Use half size (IPO = volatile)\n- Stop: middle of opening range', 'SMB teaches patience on IPO day 1. The opening range is key. Many traders get chopped trying to trade the first 5 minutes. Wait for the range, then trade the break.', '60', NULL, NULL, 'IPO Trade,ORB,Breakout,Opening Range High,Opening Range Low,IPO Stock,Recent IPO (<6mo),High Relative Volume', NULL, NULL, '2026-04-09 23:34:22.214+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('40', 'Gap and Go — Earnings Momentum', 'SMB Capital — Gap Plays', 'Earnings Gap Up', 'Stock gaps up >5% on strong earnings. Follow-through buying in first 30 minutes. Long continuation above opening range.', '- Earnings beat expectations significantly\n- Gap > 5% with volume > 2x average\n- Stock holds above VWAP in first 15 min\n- Entry on first pullback to VWAP or opening range high break\n- Stop below VWAP or opening range low\n- Target: prior resistance levels', 'Classic SMB play. The key is waiting for the first pullback rather than chasing the gap. Quality of earnings matters — revenue growth > EPS beats.', '75', NULL, NULL, 'Gap and Go,Earnings Gap Up,ORB,Trend Continuation,Earnings Beat,Revenue Beat,VWAP,Opening Range High,High Relative Volume', NULL, NULL, '2026-04-09 23:34:22.177+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('39', 'Pricing Play — Long Bounce', 'SMB Capital — Offering Plays', 'Reversal', 'After offering is priced (usually after hours), stock often gaps down to or below offering price. Long bounce off offering price level.', '- Offering priced (press release confirms price)\n- Stock trades at or below offering price\n- Volume confirms capitulation\n- Entry near offering price with tight stop\n- Target: VWAP or prior support turned resistance', 'Offering price acts as strong support because institutions bought at that level. They defend their position. Key risk: if offering price breaks, there''s no floor.', '65', NULL, NULL, 'Offering Play,Post-Offering Bounce,Reversal,VWAP Bounce,Offering,Pricing,Offering Price', NULL, NULL, '2026-04-09 23:34:22.14+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('38', 'ATM Offering Play — Short', 'SMB Capital — Offering Plays', 'Другой', 'Stock announces ATM offering (shelf registration). Price drops on dilution fear. Short into the bounce after initial panic selling.', '- ATM offering confirmed (SEC filing)\n- Price dropped >5% on news\n- Volume spike > 3x average\n- Wait for first bounce attempt\n- Entry on failed bounce / rejection at VWAP\n- Stop above pre-market high', 'One of SMB Capital''s core plays. ATM offerings create sustained selling pressure as the company sells shares into the open market. Key: don''t short the initial drop, wait for the bounce attempt and short the failure.', '80', NULL, NULL, 'Offering Play,ATM Offering,Fade Trade,VWAP Rejection,Offering,ATM,S-1 Filing,High Relative Volume,Volume Spike', NULL, NULL, '2026-04-09 23:34:22.098+00', NULL, NULL) ON CONFLICT DO NOTHING;
