INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('32', 'AEHR', '2 Day long', 'Second Day Play', NULL, 'Volume 50k\n', 'Вышла новость об офферинге что потенциально сильный негатив для 2 day long AEHR — офферинг (очень коротко)\nОбъявили ATM размещение до $60 млн\nБудут продавать акции постепенно по рынку\nСмысл:\n➝ Дилюция → давление вниз (short bias)\n➝ Не жесткий слив, а растянутый\nВывод:\n\n👉 Новость медвежья краткосрок\n👉 Смотри реакцию: держат цену = сильный спрос, падает = чистый шорт', '70', 'https://www.tradingview.com/x/TZQz4RJK/', '["AEHR"]', 'Offering, Second Day, All Time High, Market Weak, High Volatility, News Risk', NULL, NULL, '2026-04-09 17:24:07.837+00', NULL, NULL) ON CONFLICT DO NOTHING;
