INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('33', 'XOM, CVX, CNQ, BP ,SHEL, EQNR ,COP  macro (2026-04-08)', 'News Trupm', NULL, NULL, 'Гэп > 5%\nНа премаркете показывают слабость \n\n', 'Новость о перемирие США и Иран на две недели\nРеакция: gap_down\nИ с открытие все падали первые 5 минут \nпотом начали расти и в итоге закрылись на хаях ', '70', NULL, '[""]', 'Gap Down, News, Sector Move', 'event', '9', '2026-04-09 19:32:10.298+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('34', 'Pricing strategy', 'Pricing', 'Другой', 'Выше цены прайсинга\nОбъем на премаркете \nАкция показывает силу на премаркете\n', 'Объявление цены прайсинга на хаях а не на лаях\nGap down (это нормально для прайсинга)\nАкция торговалась выше цены прайсинга', NULL, '70', 'https://www.tradingview.com/x/Wi3MRLsU/', '["SPIR\\nПрайсинг объявили на хаях\\nАкция показывает силу на премаркете\\nТорговалась выше цены прайсинга\\nGap down -14.5%\\nPremarket Volume: 1,2 M"]', 'Gap Down, Pricing, Reversal, VWAP, Imbalance, OPG, Relative Strength, Opening Imbalance (OPG), OPG TO DAY, Over $100, Over $500, $20–$100, Small Cap, Finance', NULL, NULL, '2026-04-09 19:49:52.648+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('28', 'PLTR other (2026-04-09)', '2 day Gap down Short', 'other', '2 day short, пробил локальную недельную поддержку, под вчерашнем закрытием рядом с лоем вчерашнего дня буду брать опг to day', 'R.Volume 1.8 First day\nPremarket Volume before open 2.5kk\nWeak Premarket\nWeak open\nUnder Yesterday close\n8:30 already below premarket\nIGV, Sector weak.\nTP, 1/2 first day move', 'Что сработало: Перед открытием уже началось падение.\nСтопы не выбивало, Идеальная твх за 30-15 мин перед открытием, не реагировала на рынок\nВывод: Можно было закладывать больший риск, и покрывать частями и ждать, так же в процессе давала шансы добрать\n', '70', 'https://www.tradingview.com/x/0BVXZ0qL/', '["PLTR"]', 'Gap Down, Breakout, Liquidity Sweep, Sector Move, Yesterday Low, Yesterday Close, Open Price, Daily Support, Market Weak, High Volatility, Sector Weak', 'trade', '87', '2026-04-09 15:23:59.387+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('1', 'Healthcare (2026-04-07)', 'Sector Move', NULL, 'Рыночная тема: Healthcare', NULL, 'Акции крупных медицинских страховщиков — UnitedHealth, Humana и CVS Health — выросли на 6–10% в ходе предпродовой сессии после того, как CMS объявила о повышении выплат по программе Medicare Advantage на 2,48% в 2027 году. Это показатель оказался лучше ожиданий рынка, особенно на фоне того, что в начале года предложенная надбавка в 0,99% уже обвалила акции UnitedHealth почти на 20% за один день.\nТикеры: UNH, CVS, HUM, CNC, MOH', NULL, 'https://www.tradingview.com/x/Kx08uyL8/\nhttps://www.tradingview.com/x/RoAZqVUP/\nhttps://www.tradingview.com/x/YlaCWNQE/\nhttps://www.tradingview.com/x/83k2rYJq/\nhttps://www.tradingview.com/x/aq07OYla/', '["UNH, Принт по гепу, рисовки в маркет превратились","CVS, Принт против гепа.","HUM, Принт против гепа.","CNC, Принт flat.","MOH, Принт против гепа."]', 'Reversal, Gap Up, Breakout, News, Sector Move, Relative Strength, Wide Spread, High Volatility, News Risk, Market Weak', 'dailyfeed', '17', '2026-04-09 10:30:06.853+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('9', 'Weak Open Short — Gap Up Fail', 'SMB Capital — Short Setups', 'Earnings Gap Up', 'Акция gap up >5% но open weak — первый 5-мин бар red\nVWAP immediately turns down\nVolume heavy on sell side\nКаталист не достаточно сильный для sustained move\nSector/market weak', '- Gap up >5% but opens weak\n- First 5-min candle: bearish (close < open)\n- VWAP slope negative from open\n- Heavy selling volume first 5 min\n- No strong fundamental catalyst\n- Entry: break below first 5-min low\n- Stop: above first 5-min high or VWAP\n- Target: gap fill (yesterday close)', 'Gap up fail — когда рынок отвергает gap. Часто на weak catalysts: minor upgrades, sector sympathy plays, pre-market pump.\n\nСамый надёжный short intraday. Win rate ~60%.\n\nНе путать с earnings gap ups — те часто имеют real buying и recover. Gap up fails работают на слабых catalyst.', '74', 'https://www.tradingview.com/x/DfPrCSB8/\nhttps://www.tradingview.com/x/TLWHHeMC/', '["TSLA\\nNo weak open*\\nGap up из за рынка\\nGap up 4.95%\\nПервая пятимунатная свеча красная\\nVWAP сразу развернулся вниз\\nКатализатора не было. Разве что 7.04.2026 вышел downgrade от JP Morgan.\\nРынок был слабый упал на 1.25 %\\n\\n","Сравнение QQQ и TSLA"]', 'short, gap-fail, morning, reliable', NULL, NULL, '2026-04-09 10:30:06.853+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('10', 'Parabolic Short — Blow-Off Top', 'SMB Capital — Short Setups', 'Reversal', 'Акция выросла >30% за 1-2 дня без fundamental catalyst\nПоследняя волна роста — вертикальная (parabolic)\nVolume climax — огромный volume на top\nFirst red candle с high volume после parabolic move\nSSR не активен (или есть shares to short)', '- Move >30% in 1-2 days\n- No real catalyst (just momentum/social media)\n- Volume climax bar at top\n- First lower high on 5-min chart\n- Spread widening at top\n- Entry: break below first consolidation after climax\n- Stop: above HOD (tight)\n- Target: 50% retrace of the move or VWAP', 'High risk / high reward. Самый опасный но и самый прибыльный short setup.\n\nПравила SMB для parabolic shorts:\n1. Никогда не шортить на пути вверх — только после confirmation top\n2. Size small — максимум 50% обычного размера\n3. Стоп жёсткий — HOD +$0.25\n4. Не шортить low float (<5M) parabolics — могут squeeze бесконечно\n\nПримеры: GME, AMC blow-offs, random small cap pumps.', '65', NULL, '[""]', 'short, parabolic, high-risk, blow-off', NULL, NULL, '2026-04-09 10:30:06.853+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('5', 'FOMC Fade — Post-Decision Reversal', 'SMB Capital - Macro & Sector Plays', 'Другой', 'FOMC decision day в 2:00 PM ET\nInitial move >1% на SPY в первые 15 минут после решения\nMove driven by algo/knee-jerk reaction\nPowell press conference начинается в 2:30 PM\nReversal signs: volume spike + exhaustion candle', '- FOMC decision released at 2:00 PM ET\n- Initial move >1% on SPY\n- Wait for exhaustion (15-30 min after decision)\n- Powell presser reversal typical at 2:30-3:00 PM\n- Entry: reversal candle after initial move\n- Stop: beyond the extreme of initial move\n- Target: full retrace of FOMC initial move', 'FOMC fade — один из самых statistically reliable сетапов. Initial reaction часто reversed полностью к close.\n\nStatistics: ~60% FOMC days reverse the initial move. Powell press conference creates the second volatility wave.\n\nРиск: иногда initial move продолжается (hawkish surprise). Размер позиции = 50% от обычного.\n\nSMB правило: не торговать первые 15 минут после FOMC. Ждать clarity.', '70', NULL, '[""]', 'fomc, macro, fade, event-driven', NULL, NULL, '2026-04-09 10:30:06.853+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('15', 'Earnings Gap Down — Short the Failed Bounce', 'SMB Capital - Earnings Plays', 'Earnings Gap Down Short', 'Gap down >7% на miss по EPS или guidance cut\nОбъём premarket >300K\nСтруктура: opening drive down → bounce attempt → fail at resistance\nResistance: VWAP, prior close, declining 9 EMA\nSector weak или нейтральный', '- EPS miss или guidance cut\n- Gap down >7%\n- Bounce to VWAP or 38.2% retrace fails\n- Lower highs формируются на bounce\n- Volume fade на bounce\n- No major support nearby ($1-2 range)\n- Risk: above VWAP or bounce high\n- Target: LOD retest or extension', 'Ждём failed bounce к VWAP после утреннего sell-off. Вход short на rejection от VWAP или declining 9 EMA. Стоп выше VWAP. Тейк — retest LOD и ниже.\n\nОсторожно с акциями <$10 и с очень высоким short interest — могут сквизнуть.\n\nПримеры: SNAP earnings, ZM earnings drops, PYPL guidance cuts.', '82', NULL, NULL, 'earnings, gap-down, short, reversal', NULL, NULL, '2026-04-09 10:30:06.853+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('14', 'Earnings Winner — Day 2 Continuation', 'SMB Capital - Earnings Plays', 'Second Day Play', 'Day 1: сильный earnings gap up с close near HOD\nDay 2 gap up или flat open above Day 1 close\nОбъём Day 1 был >3x 20-day average volume\nНет распродажи premarket Day 2\nSector momentum positive', '- Day 1 closed >80% от range\n- Day 1 volume >3x average\n- Day 2 premarket: not fading below Day 1 close\n- Opening range first 5 min: above VWAP\n- Catalyst still fresh — upgrades/coverage\n- Entry: hold of Day 1 close or VWAP\n- Stop: below Day 1 close\n- Target: 1.5x Day 1 range extension', 'SMB classic Day 2 play. Самые сильные earnings movers продолжают движение на Day 2 из-за institutional buying, short covering, и upgrades overnight.\n\nКлюч — Day 1 close должен быть near HOD (закрытие силы). Если Day 1 закрылся с длинной верхней тенью, Day 2 обычно слабый.\n\nTrack: NVDA, META, AMZN post-earnings Day 2 moves.', '78', NULL, NULL, 'earnings, continuation, day-2, momentum', NULL, NULL, '2026-04-09 10:30:06.853+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('6', 'IPO Day 1 — Opening Range Breakout', 'SMB Capital — IPO Plays', 'IPO Day Trade', 'Новый IPO первый день торгов\nОткрылся выше IPO price с premium >20%\nFirst 15 min range establishes\nInstitutional demand visible (large prints on tape)\nSector hot (tech, AI, biotech catalysts)', '- IPO price vs open price: premium >20%\n- First 15-min range: tight (<5% of price)\n- Volume first 15 min: massive (>5M shares)\n- Large block prints on tape\n- No lockup expiry imminent\n- Entry: break above 15-min high\n- Stop: below 15-min low or VWAP\n- Target: 2x opening range height', 'IPO Day 1 — unique setup потому что нет технических уровней. Всё определяется supply/demand.\n\nПравила:\n1. Торговать только IPO с strong demand (oversubscribed)\n2. Ждать первый 15-мин range — никогда не покупать на open\n3. Size small — IPO volatile\n4. Быть готовым к wide stops\n\nRecent examples: ARM Holdings, Instacart, Reddit IPO days.', '68', NULL, '[""]', 'ipo, day-1, opening-range, high-vol', NULL, NULL, '2026-04-09 10:30:06.853+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('12', 'VWAP Reclaim — Mean Reversion Long', 'SMB Capital — Momentum Setups', 'Reversal', 'Акция упала ниже VWAP утром на weak selling (low volume)\nНачинает формировать higher lows ниже VWAP\nVolume pick up на reclaim candle\nОбщий рынок (SPY) стабилен или растёт\nАкция имеет дневной uptrend (выше 20 SMA daily)', '- Stock pulled back to/below VWAP on declining volume\n- Higher lows forming (ascending triangle pattern)\n- Volume increase on reclaim candle\n- SPY not tanking\n- Daily trend is up (above 20 SMA)\n- Entry: break above VWAP with volume\n- Stop: below last higher low\n- Target: HOD retest', 'Mean reversion к VWAP — один из самых reliable сетапов. Работает когда selling exhaustion очевиден (volume dry up below VWAP).\n\nЛучше всего работает 10:30-11:30 AM ET после утренней волатильности.\n\nНе торговать если акция имеет negative catalyst (earnings miss, downgrade). Только для технических pullback.', '80', NULL, '[""]', 'vwap, mean-reversion, long, reliable', NULL, NULL, '2026-04-09 10:30:06.853+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('8', 'Flag Pattern Breakout', 'SMB Capital - Breakout Patterns', 'Breakout', 'Strong initial move (pole) >5% с high volume\nConsolidation 15-45 min с declining volume (flag)\nFlag retraces <38.2% of pole\nVWAP ниже flag — supportive\nMarket (SPY) stable или bullish', '- Pole move >5% on volume\n- Consolidation (flag) 3-8 candles on 5-min\n- Volume declining during flag\n- Flag <38.2% retrace of pole\n- Break above flag high on volume surge\n- Entry: break of flag high\n- Stop: below flag low\n- Target: measured move (pole length from breakout)', 'Классический continuation pattern. Один из самых чистых сетапов в day trading.\n\nFlag должен быть tight — если широкий (>50% retrace), это уже не flag а reversal.\n\nLook for: tight candles, declining volume in flag, clean break with volume. Measured move target обычно достигается в 65% случаев.\n\nSMB traders ищут 2-3 flag patterns per day в leading stocks.', '82', NULL, NULL, 'breakout, flag, continuation, clean', NULL, NULL, '2026-04-09 10:30:06.853+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('26', 'Scalping 1-Min Bounce', NULL, 'Scalp', 'Stock with sub-5M float, RVOL 3+, support level confirmed', '1-min entry, 0.05-0.15 target, stop 0.10 below', 'Quick execution critical, needs tight spreads', '6', NULL, NULL, NULL, NULL, NULL, '2026-04-09 10:30:06.853+00', '2026-04-09 23:38:31.835+00', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('25', 'HOD Failure Short', NULL, 'Short', 'Gap up then fails at HOD, 2M+ premarket float', 'Resistance at HOD confirmed, short entry near resistance', 'Avoid on strong earnings names - Tech exception', '7', NULL, NULL, NULL, NULL, NULL, '2026-04-09 10:30:06.853+00', '2026-04-09 23:38:29.979+00', NULL) ON CONFLICT DO NOTHING;
