INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('23', 'VWAP Support Bounce', NULL, 'Support', 'Stock consolidates at VWAP, RVOL 1.5+, clean candle bounce', 'VWAP touched, entry on close above VWAP, resistance plotted', 'Works in trending markets - Morning preferred', '7', NULL, NULL, NULL, NULL, NULL, '2026-04-09 10:30:06.853+00', '2026-04-09 23:38:25.961+00', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('7', 'Range Break — Consolidation Squeeze', 'SMB Capital - Breakout Patterns', 'Breakout', 'Акция торгуется в tight range >30 минут\nRange сужается (squeeze) — Bollinger Bands narrowing\nVolume declining в range\nАкция near HOD или at significant level\nCatalyst present (upcoming event, sector move)', '- Range <2% for >30 min\n- Volume declining in range\n- ATR squeeze visible\n- Stock near HOD or key daily level\n- Clear direction bias (above/below VWAP)\n- Entry: break of range with volume >2x range average\n- Stop: opposite side of range\n- Target: range width x 2 extension', 'Compression leads to expansion. Длительная консолидация создаёт energy для big move.\n\nЧасто работает в midday (11-1 PM) когда утренний momentum затухает и формируется новый range.\n\nRisk management: если breakout immediately fails (1 candle), это false breakout — выходить немедленно. Real breakouts не дают re-entry ниже breakout level.', '72', NULL, NULL, 'breakout, squeeze, range, patience', NULL, NULL, '2026-04-09 10:30:06.853+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('11', 'Red to Green Move', 'SMB Capital — Momentum Setups', 'Reversal', 'Акция открылась red (ниже yesterday close)\nНет negative catalyst — продажа на общем рынке или sector rotation\nНачинает recovery с volume build\nReclaims yesterday close (red to green)\nStrong relative strength vs SPY', '- No company-specific bad news\n- Pre-market selling was sector/market-wide\n- Recovery on increasing volume\n- Break above yesterday close\n- Relative strength vs SPY positive\n- Entry: first pullback after R2G move\n- Stop: below the red-to-green level\n- Target: prior day high or VWAP from prior day', 'Red to Green — сигнал институционального buying. Кто-то считает цену attractive и набирает позицию.\n\nСамые сильные R2G moves происходят в первый час торгов. Если R2G происходит после 11 AM — менее надёжно.\n\nTrack: крупные tech names (AAPL, MSFT, GOOGL) часто показывают R2G в дни market weakness.', '77', NULL, '[""]', 'reversal, red-to-green, relative-strength', NULL, NULL, '2026-04-09 10:30:06.853+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('13', 'Opening Drive — Momentum Ignition', 'SMB Capital — Momentum Setups', 'Intraday Momentum', 'Гэп >3% с каталистом (news, upgrade, sector move)\nPremarket volume >200K\nBid-ask tight (<0.05 для stocks >$20)\nLevel 2 показывает стэковый bid\nFirst 1-min candle closes near high с volume >50K', '- Clear catalyst identified\n- Gap >3% with volume\n- First 1-min candle: bullish close\n- VWAP slope positive\n- No immediate overhead resistance ($0.50)\n- Entry: break of 1-min high\n- Stop: below 1-min low or VWAP\n- Target: next whole dollar / premarket high', 'Самый быстрый setup — первые 5-15 минут торгов. Вход на break первой 1-мин свечи с volume confirmation. Всё решается за 2-5 минут.\n\nОшибка новичков: входить в открытие без подтверждения первой свечи. Пропускайте если первая свеча — doji или bearish.\n\nWin rate ~55%, но R:R обычно 3:1+. Один из хлебных сетапов SMB.', '75', NULL, '[""]', 'momentum, opening, speed, A-setup', NULL, NULL, '2026-04-09 10:30:06.853+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('2', 'Trade Review Checklist', 'Trillium - Position Management', 'Другой', 'Выполнять для КАЖДОГО трейда, win или loss\nЗаполнять в течение 30 минут после закрытия позиции\nЧестная оценка — никакого hindsight bias', '- Был ли это мой setup из плейбука?\n- Дождался ли я confirmation?\n- Правильный ли был sizing?\n- Стоп был определён до входа?\n- Следовал ли я своему стопу?\n- Был ли entry timing оптимальным?\n- Достаточно ли я держал winner?\n- Не передержал ли я loser?\n- Что я сделал бы по-другому?\n- Какой урок вынес?', 'Без review нет improvement. Каждый трейд — это data point.\n\nSMB требует от всех трейдеров вести journal и review. Без этого невозможно идентифицировать edge.\n\nPlayback method: в конце дня пересмотри каждый трейд на charts. Отметь entry/exit/stop. Оцени 1-10.\n\nЕженедельный review: top 3 best trades, top 3 worst trades, паттерны ошибок.', '100', NULL, '[""]', 'review, process, discipline, must-do', NULL, NULL, '2026-04-09 10:30:06.853+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('3', 'Position Sizing Framework', 'Trillium - Position Management', 'Другой', 'Применять ко ВСЕМ сетапам без исключений\nМаксимальный риск на трейд: 1% от счёта\nA+ setups: полный размер (1%)\nB setups: 50-75% от полного размера\nC setups: 25-50% или пропуск', '- Account risk per trade: MAX 1%\n- A+ setup: full size\n- B setup: 50-75% size\n- C setup: 25-50% size\n- Daily loss limit: 3% of account\n- Weekly loss limit: 5% of account\n- Stop ALWAYS defined BEFORE entry\n- No averaging down on losers', 'SMB Capital Risk Management:\n\n1. Новичок (<6 мес): 0.25% risk per trade, max 3 trades/day\n2. Developing (6-12 мес): 0.5% risk per trade, max 5 trades/day\n3. Experienced (>1 год с profit): 1% risk per trade, no daily limit\n\nGolden rule: если проиграл 3 трейда подряд — стоп на день. Не пытайся отбить.\n\nPosition sizing formula: Shares = (Account * Risk%) / (Entry - Stop)', '95', NULL, '[""]', 'risk, sizing, rules, critical', NULL, NULL, '2026-04-09 10:30:06.853+00', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.playbook (id, name, folder, setup_type, conditions, checklist, notes, confidence_level, screenshot_url, screenshot_notes, tags, source_type, source_id, created_at, deleted_at, parent_id) VALUES ('4', 'CPI Morning Gap — Trend Day Trade', 'SMB Capital - Macro & Sector Plays', 'Другой', 'CPI data release 8:30 AM ET\nSignificant deviation from expectations (>0.2%)\nSPY gaps >0.5% on the data\nBond yields move sharply in same direction\nFirst 15-мин range clean (not choppy)', '- CPI deviation from consensus >0.2%\n- SPY gap >0.5%\n- Bond yields (TNX) confirming direction\n- VIX expansion\n- First 15-min candle establishes direction\n- Entry: with trend after first pullback\n- Stop: opposite side of first 15-min range\n- Target: 2-3x first hour range (trend day potential)', 'CPI days часто становятся trend days — одно направление весь день.\n\nЕсли CPI горячий (выше ожиданий) — sell the open, short rallies.\nЕсли CPI мягкий (ниже ожиданий) — buy pullbacks.\n\nTrend day characteristics: closes near HOD/LOD, TICK persistent, breadth one-sided.\n\nBest stocks for CPI plays: rate-sensitive (banks, REITs, tech growth).', '73', NULL, '[""]', 'cpi, macro, trend-day, morning', NULL, NULL, '2026-04-09 10:30:06.853+00', NULL, NULL) ON CONFLICT DO NOTHING;
