INSERT INTO public.trades (id, ticker, date, setup, side, event_type, entry, exit, stop, result, pnl, r_multiple, hold_time, slippage, market_cap, "float", relative_volume, session, screenshot_url, screenshot_notes, notes, what_worked, what_failed, conclusion, trader, tags, event_id, pattern_id, playbook_id, created_at, deleted_at) VALUES ('92', 'SPIR', '2026-04-09', NULL, 'Long', 'other', '17.6000', '19.2000', '17.3000', 'win', NULL, '5.00', NULL, '6.00', '652 M ', '26.88 M', '1.80', 'regular', 'https://www.tradingview.com/x/EtvtGAhA/', '[""]', 'SPIR Pricing\nSpire Global объявила о частном размещении (private placement) на $70 млн, продав 5,0 млн акций класса A по цене $14.00 за акцию.\n\nПривлечённые средства будут направлены на:\nоборотный капитал (working capital)\nинициативы роста, включая:\nкосмическую разведку (space reconnaissance)\nрешения в области погодных данных', 'Pricing > 14 ', NULL, 'Был хороший мув первые пол часа. Зашел по цене 17.60. Далее акция опустилась до уровня своего опена, ретестнула и пошла дальше вверх и вышел по 19.20\n', 'Максат', 'Pricing, Offering', NULL, NULL, NULL, '2026-04-09 17:32:03.359+00', NULL) ON CONFLICT DO NOTHING;
