INSERT INTO public.trades (id, ticker, date, setup, side, event_type, entry, exit, stop, result, pnl, r_multiple, hold_time, slippage, market_cap, "float", relative_volume, session, screenshot_url, screenshot_notes, notes, what_worked, what_failed, conclusion, trader, tags, event_id, pattern_id, playbook_id, created_at, deleted_at) VALUES ('90', 'CRWV', '2026-04-09', NULL, 'Short', 'news', '91.7700', '87.3800', '93.0400', 'win', NULL, '4.00', '2часа', '5.00', '45,43B', '320.04M', '3.87', 'regular', 'https://www.tradingview.com/x/IQj1LJmB/\nhttps://www.tradingview.com/x/W2EYFU7A/', '["",""]', 'Сначала вышло новость связанное что " Акции Meta и CoreWeave подскочили на фоне масштабной сделки по приобретению ИИ на сумму 21 миллиард долларов " на фоне этого акция выросла . Потом она объявила offering " Компания CoreWeave предлагает конвертируемые облигации на сумму 3 млрд долларов со сроком погашения в 2032 году " после этого цена начала падать.\n\nРАССМАТРИВАЛ В ШОРТ ПОСМОТРЕЛ ФУНДОМЕНТАЛЬНО, КОМПАНИЯ В ДАННОЕ ВРЕМЯ УБЯТОЧНАЯ ДОЛГОВ МНОГО И ТЕХНИЧЕСКИ ГРАФИК У НЕЕ МЕДВЕЖЫЙ И НА ПРЕМАРКЕТЕ ОНА ВЕРНУЛА ПОЛОВИНУ РОСТА\n', 'ИДЕЯ СРАБОТАЛА РАССМАТРИВАЛ ЕЕ НА ИНТРОДЭЙ ПОТОМУ ЧТО С ОТКРЫТИЕ ОНА МОГЛА СНАЧАЛА НА ВВЕРХ ПОЙТИ И ПОТОМ УЖЕ ВНИЗ. ЦЕНА ОТКРЫЛАСЬ НАЧАЛА РАСТИ И УЖЕ 09:41 МИНУТЕ НАЧАЛА ПАДАТЬ ПРОБИЛА СВОЙ ОПЕН И ПАДАЛА. ЧЕРЕЗ ВРЕМЯ ЦЕНА НАЧАЛА РАСТИ И ВЫШЛА НОВОСТЬ " ТРАМП ПОПРОСИЛ НЕТАНЯХУ НЕ БИТЬ ПО ЛИВАНУ ДЛЯ ПЕРЕГОВОРОВ " НА ФОНЕ ЭТОЙ НОВОСТИ РЫНОК НАЧАЛ РАСТИ И АКЦИЯ ТОЖЕ НАЧАЛА РАСТИ ПРОБИЛА СВОЙ ОПЕН СДЕЛАЛА HIGHER HIGH ', NULL, NULL, 'Умид', 'Gap Up, Offering, Yesterday Low, Yesterday Close, SMA50, Open Price', NULL, NULL, NULL, '2026-04-09 17:22:55.138+00', NULL) ON CONFLICT DO NOTHING;
